/*
 * Date picker styles: the calendar, the popover and the select control. The
 * tokens are resolved for the Electron theme, as the data-button module does. Values that differ between light and dark use
 * light-dark, which follows the nearest color-scheme scope. App colors come
 * from the foundations theme variables (ui/app/globals.css).
 *
 * The day labels inherit their letter spacing.
 */

@layer theme, base, components, utilities;

@layer components {
  .selectControl,
  .popover,
  .calendarContainer {
    /* Control scale. The radii are the theme's radius tokens. */
    --ck-control-font-size-lg: 1rem;
    --ck-control-font-size-md: 0.875rem;
    --ck-control-font-size-sm: 0.75rem;
    --ck-control-gutter-2xs: 0.375rem;
    --ck-control-gutter-lg: 0.875rem;
    --ck-control-gutter-md: 0.75rem;
    --ck-control-gutter-pill-scaling: 1.3;
    --ck-control-gutter-sm: 0.625rem;
    --ck-control-gutter-xl: 1rem;
    --ck-control-gutter-xs: 0.5rem;
    --ck-control-icon-size-lg: 1.25rem;
    --ck-control-icon-size-md: 1.125rem;
    --ck-control-icon-size-sm: 1rem;
    --ck-control-icon-size-xs: 0.875rem;
    --ck-control-radius-lg: var(--radius-lg);
    --ck-control-radius-md: var(--radius-md);
    --ck-control-radius-sm: var(--radius-sm);
    --ck-control-radius-xl: var(--radius-xl);
    --ck-control-size-2xl: 2.75rem;
    --ck-control-size-2xs: 1.5rem;
    --ck-control-size-3xl: 3rem;
    --ck-control-size-3xs: 1.375rem;
    --ck-control-size-lg: 2.25rem;
    --ck-control-size-md: 2rem;
    --ck-control-size-sm: 1.75rem;
    --ck-control-size-xl: 2.5rem;
    --ck-control-size-xs: 1.625rem;
    --motion-duration-fast: 0.16s;
    --ck-motion-ease-basic: ease;

    /* Theme colors (Electron). alpha-NN is the text color at NN percent. */
    --alpha-05: color-mix(in oklab, var(--ck-palette-ink) 5%, transparent);
    --alpha-06: color-mix(in oklab, var(--ck-palette-ink) 6%, transparent);
    --alpha-08: color-mix(in oklab, var(--ck-palette-ink) 8%, transparent);
    --color-text: var(--ck-palette-ink);
    --color-text-muted: var(--ck-palette-ink-secondary);
    --color-text-emphasized: var(--ck-palette-ink);
    --color-text-inverse: var(--ck-palette-label-button-primary);
    --color-text-unavailable: var(--ck-palette-ink-tertiary);
    --color-panel-elevated: var(--ck-palette-surface-elevated-primary);
    --color-fill-disabled: var(--alpha-05);
    --color-stroke-disabled: var(--alpha-06);
    --color-fill-primary-transparent-hover: var(
      --ck-palette-surface-button-secondary-hover
    );
    --color-fill-primary-transparent-pressed: light-dark(
      color-mix(in oklab, var(--ck-palette-ink) 12%, transparent),
      color-mix(in oklab, var(--ck-palette-ink) 16%, transparent)
    );
    --color-fill-primary-soft-alpha: color-mix(
      in oklab,
      var(--ck-palette-ink) 2.5%,
      transparent
    );
    --color-fill-primary-soft-alpha-hover: light-dark(
      color-mix(in oklab, var(--ck-palette-ink) 12%, transparent),
      color-mix(in oklab, var(--ck-palette-ink) 16%, transparent)
    );
    --color-fill-primary-soft-alpha-active: light-dark(
      color-mix(in oklab, var(--ck-palette-ink) 16%, transparent),
      color-mix(in oklab, var(--ck-palette-ink) 20%, transparent)
    );
    --color-ring: var(--ck-palette-border-focus);
    --color-ring-danger: var(--color-status-danger-fill);
    --ck-field-outline-border-color: var(--ck-palette-border-heavy);
    --ck-field-outline-border-color-hover: light-dark(
      color-mix(in oklab, var(--ck-palette-ink) 25%, transparent),
      color-mix(in oklab, var(--ck-palette-ink) 30%, transparent)
    );
    --ck-field-border-color-invalid: var(--color-status-danger);
    --ck-field-placeholder-text-color: var(--ck-palette-ink-tertiary);
    --ck-curve-enter: cubic-bezier(0.19, 1, 0.22, 1);
    --ck-curve-exit: cubic-bezier(0.8, 0, 0.4, 1);
    --ck-curve-move: cubic-bezier(0.65, 0, 0.35, 1);
  }

  /* ---------------------------------------------------------------- trigger */

  .selectControl {
    justify-content: space-between;
    align-items: center;
    gap: var(--ck-select-control-gap);
    height: var(--ck-select-control-size);
    padding: 0 var(--ck-select-control-gutter);
    border-radius: var(--ck-select-control-radius);
    cursor: pointer;
    font-size: var(--ck-select-control-font-size);
    font-weight: var(--ck-select-control-font-weight, 500);
    line-height: 1.5rem;
    text-align: left;
    transition-duration: var(--motion-duration-fast);
    transition-property: color;
    transition-timing-function: var(--ck-motion-ease-basic);
    user-select: none;
    white-space: nowrap;
    flex-shrink: 0;
    display: inline-flex;
    position: relative;
  }

  .selectControl[data-ck-disable-pressable] {
    --scale: 1;
  }

  .selectControl::before {
    border-radius: inherit;
    content: "";
    transition-duration: var(--motion-duration-fast);
    transition-property:
      opacity, background-color, transform, box-shadow, border-color;
    transition-timing-function: var(--ck-motion-ease-basic);
    will-change: transform;
    display: block;
    position: absolute;
    inset: 0;
  }

  .selectControl::after {
    border-radius: inherit;
    content: "";
    pointer-events: none;
    transition-duration: var(--motion-duration-fast);
    transition-property: transform;
    transition-timing-function: var(--ck-motion-ease-basic);
    will-change: transform;
    display: block;
    position: absolute;
    inset: 0;
  }

  .selectControl:focus {
    outline: none;
  }

  .selectControl:focus-visible::after {
    outline: 2px solid var(--ck-action-ring-color, var(--color-ring));
    outline-offset: var(--ck-select-control-ring-offset, 2px);
  }

  .selectControl:where([data-size="3xs"]) {
    --ck-select-control-size: var(--ck-control-size-3xs);
    --ck-select-control-gutter: var(--ck-control-gutter-2xs);
    --ck-select-control-font-size: var(--ck-control-font-size-sm);
    --ck-select-control-gap: 4px;
    --ck-select-control-radius: var(--ck-control-radius-sm);
    --ck-start-icon-size: var(--ck-control-icon-size-xs);
    --ck-start-icon-offset: 0;
    --ck-start-icon-pill-offset: 0;
    --clear-size: 14px;
    --ck-clear-icon-size: 14px;
    --ck-date-clear-size: 12px;
    --ck-date-clear-icon-size: 11px;
    --ck-date-clear-offset: 0px;
    --ck-date-clear-pill-offset: -1px;
    --ck-dropdown-icon-offset: 0;
    --ck-dropdown-icon-pill-offset: 0;
    --ck-dropdown-icon-width: 6px;
    --ck-dropdown-icon-height: 9px;
    --ck-dropdown-chevron-icon-width: 8px;
    --ck-dropdown-chevron-icon-height: 5px;
    --ck-indicator-wrapper-gap: calc(var(--spacing) * 1);
    --ck-indicator-wrapper-gutter: 0;
  }

  .selectControl:where([data-size="2xs"]) {
    --ck-select-control-size: var(--ck-control-size-2xs);
    --ck-select-control-gutter: var(--ck-control-gutter-xs);
    --ck-select-control-font-size: var(--ck-control-font-size-sm);
    --ck-select-control-gap: 6px;
    --ck-select-control-radius: var(--ck-control-radius-sm);
    --ck-start-icon-size: var(--ck-control-icon-size-sm);
    --ck-start-icon-offset: 0;
    --ck-start-icon-pill-offset: 0px;
    --clear-size: 16px;
    --ck-clear-icon-size: 14px;
    --ck-date-clear-size: 14px;
    --ck-date-clear-icon-size: 13px;
    --ck-date-clear-offset: -1px;
    --ck-date-clear-pill-offset: -3px;
    --ck-dropdown-icon-offset: 0;
    --ck-dropdown-icon-pill-offset: 0;
    --ck-dropdown-icon-width: 6px;
    --ck-dropdown-icon-height: 9px;
    --ck-dropdown-chevron-icon-width: 8px;
    --ck-dropdown-chevron-icon-height: 5px;
    --ck-indicator-wrapper-gap: calc(var(--spacing) * 1);
    --ck-indicator-wrapper-gutter: 0;
  }

  .selectControl:where([data-size="xs"]) {
    --ck-select-control-size: var(--ck-control-size-xs);
    --ck-select-control-gutter: var(--ck-control-gutter-xs);
    --ck-select-control-font-size: var(--ck-control-font-size-md);
    --ck-select-control-gap: 6px;
    --ck-select-control-radius: var(--ck-control-radius-sm);
    --ck-start-icon-size: var(--ck-control-icon-size-sm);
    --ck-start-icon-offset: 0px;
    --ck-start-icon-pill-offset: 0px;
    --clear-size: 18px;
    --ck-clear-icon-size: 15px;
    --ck-date-clear-size: 16px;
    --ck-date-clear-icon-size: 13px;
    --ck-date-clear-offset: -1px;
    --ck-date-clear-pill-offset: -3px;
    --ck-dropdown-icon-offset: 0;
    --ck-dropdown-icon-pill-offset: 0;
    --ck-dropdown-icon-width: 7px;
    --ck-dropdown-icon-height: 11px;
    --ck-dropdown-chevron-icon-width: 9px;
    --ck-dropdown-chevron-icon-height: 5px;
    --ck-indicator-wrapper-gap: calc(var(--spacing) * 1);
    --ck-indicator-wrapper-gutter: 0;
  }

  .selectControl:where([data-size="sm"]) {
    --ck-select-control-size: var(--ck-control-size-sm);
    --ck-select-control-gutter: var(--ck-control-gutter-sm);
    --ck-select-control-font-size: var(--ck-control-font-size-md);
    --ck-select-control-gap: 8px;
    --ck-select-control-radius: var(--ck-control-radius-sm);
    --ck-start-icon-size: var(--ck-control-icon-size-sm);
    --ck-start-icon-offset: 0px;
    --ck-start-icon-pill-offset: -1px;
    --clear-size: 18px;
    --ck-clear-icon-size: 15px;
    --ck-date-clear-size: 16px;
    --ck-date-clear-icon-size: 13px;
    --ck-date-clear-offset: -2px;
    --ck-date-clear-pill-offset: -5px;
    --ck-dropdown-icon-offset: 0;
    --ck-dropdown-icon-pill-offset: -1px;
    --ck-dropdown-icon-width: 7px;
    --ck-dropdown-icon-height: 11px;
    --ck-dropdown-chevron-icon-width: 9px;
    --ck-dropdown-chevron-icon-height: 5px;
    --ck-indicator-wrapper-gap: calc(var(--spacing) * 1);
    --ck-indicator-wrapper-gutter: 0;
  }

  .selectControl:where([data-size="md"]) {
    --ck-select-control-size: var(--ck-control-size-md);
    --ck-select-control-gutter: var(--ck-control-gutter-md);
    --ck-select-control-font-size: var(--ck-control-font-size-md);
    --ck-select-control-gap: 8px;
    --ck-select-control-radius: var(--ck-control-radius-md);
    --ck-start-icon-size: var(--ck-control-icon-size-md);
    --ck-start-icon-offset: 0px;
    --ck-start-icon-pill-offset: -3px;
    --clear-size: 22px;
    --ck-clear-icon-size: 16px;
    --ck-date-clear-size: 18px;
    --ck-date-clear-icon-size: 15px;
    --ck-date-clear-offset: -3px;
    --ck-date-clear-pill-offset: -6px;
    --ck-dropdown-icon-offset: 0;
    --ck-dropdown-icon-pill-offset: -1px;
    --ck-dropdown-icon-width: 8px;
    --ck-dropdown-icon-height: 12px;
    --ck-dropdown-chevron-icon-width: 11px;
    --ck-dropdown-chevron-icon-height: 6px;
    --ck-indicator-wrapper-gap: calc(var(--spacing) * 1);
    --ck-indicator-wrapper-gutter: calc(var(--spacing) * 0);
  }

  .selectControl:where([data-size="lg"]) {
    --ck-select-control-size: var(--ck-control-size-lg);
    --ck-select-control-gutter: var(--ck-control-gutter-md);
    --ck-select-control-font-size: var(--ck-control-font-size-md);
    --ck-select-control-gap: 8px;
    --ck-select-control-radius: var(--ck-control-radius-md);
    --ck-start-icon-size: var(--ck-control-icon-size-md);
    --ck-start-icon-offset: -1px;
    --ck-start-icon-pill-offset: -3px;
    --clear-size: 22px;
    --ck-clear-icon-size: 16px;
    --ck-date-clear-size: 18px;
    --ck-date-clear-icon-size: 15px;
    --ck-date-clear-offset: -1px;
    --ck-date-clear-pill-offset: -5px;
    --ck-dropdown-icon-offset: 0;
    --ck-dropdown-icon-pill-offset: -1px;
    --ck-dropdown-icon-width: 8px;
    --ck-dropdown-icon-height: 12px;
    --ck-dropdown-chevron-icon-width: 11px;
    --ck-dropdown-chevron-icon-height: 6px;
    --ck-indicator-wrapper-gap: calc(var(--spacing) * 1.5);
    --ck-indicator-wrapper-gutter: calc(var(--spacing) * 0);
  }

  .selectControl:where([data-size="xl"]) {
    --ck-select-control-size: var(--ck-control-size-xl);
    --ck-select-control-gutter: var(--ck-control-gutter-lg);
    --ck-select-control-font-size: var(--ck-control-font-size-md);
    --ck-select-control-gap: 8px;
    --ck-select-control-radius: var(--ck-control-radius-lg);
    --ck-start-icon-size: var(--ck-control-icon-size-md);
    --ck-start-icon-offset: -1px;
    --ck-start-icon-pill-offset: -3px;
    --clear-size: 24px;
    --ck-clear-icon-size: 17px;
    --ck-date-clear-size: 18px;
    --ck-date-clear-icon-size: 15px;
    --ck-date-clear-offset: -1px;
    --ck-date-clear-pill-offset: -6px;
    --ck-dropdown-icon-offset: 0;
    --ck-dropdown-icon-pill-offset: -1px;
    --ck-dropdown-icon-width: 8px;
    --ck-dropdown-icon-height: 12px;
    --ck-dropdown-chevron-icon-width: 11px;
    --ck-dropdown-chevron-icon-height: 6px;
    --ck-indicator-wrapper-gap: calc(var(--spacing) * 1);
    --ck-indicator-wrapper-gutter: calc(var(--spacing) * 0.5);
  }

  .selectControl:where([data-size="2xl"]) {
    --ck-select-control-size: var(--ck-control-size-2xl);
    --ck-select-control-gutter: var(--ck-control-gutter-lg);
    --ck-select-control-font-size: var(--ck-control-font-size-lg);
    --ck-select-control-gap: 10px;
    --ck-select-control-radius: var(--ck-control-radius-xl);
    --ck-start-icon-size: var(--ck-control-icon-size-lg);
    --ck-start-icon-offset: -1px;
    --ck-start-icon-pill-offset: -3px;
    --clear-size: 24px;
    --ck-clear-icon-size: 17px;
    --ck-date-clear-size: 20px;
    --ck-date-clear-icon-size: 16px;
    --ck-date-clear-offset: -1px;
    --ck-date-clear-pill-offset: -6px;
    --ck-dropdown-icon-offset: 0;
    --ck-dropdown-icon-pill-offset: -1px;
    --ck-dropdown-icon-width: 8px;
    --ck-dropdown-icon-height: 12px;
    --ck-dropdown-chevron-icon-width: 11px;
    --ck-dropdown-chevron-icon-height: 6px;
    --ck-indicator-wrapper-gap: calc(var(--spacing) * 1.5);
    --ck-indicator-wrapper-gutter: calc(var(--spacing) * 1);
  }

  .selectControl:where([data-size="3xl"]) {
    --ck-select-control-size: var(--ck-control-size-3xl);
    --ck-select-control-gutter: var(--ck-control-gutter-xl);
    --ck-select-control-font-size: var(--ck-control-font-size-lg);
    --ck-select-control-gap: 10px;
    --ck-select-control-radius: var(--ck-control-radius-xl);
    --ck-start-icon-size: var(--ck-control-icon-size-lg);
    --ck-start-icon-offset: -1px;
    --ck-start-icon-pill-offset: -3px;
    --clear-size: 24px;
    --ck-clear-icon-size: 17px;
    --ck-date-clear-size: 20px;
    --ck-date-clear-icon-size: 16px;
    --ck-date-clear-offset: -1px;
    --ck-date-clear-pill-offset: -6px;
    --ck-dropdown-icon-offset: 0;
    --ck-dropdown-icon-pill-offset: -2px;
    --ck-dropdown-icon-width: 9px;
    --ck-dropdown-icon-height: 13px;
    --ck-dropdown-chevron-icon-width: 12px;
    --ck-dropdown-chevron-icon-height: 7px;
    --ck-indicator-wrapper-gap: calc(var(--spacing) * 1.5);
    --ck-indicator-wrapper-gutter: calc(var(--spacing) * 1);
  }

  .selectControl:where([data-pill]) {
    --ck-select-control-radius: 9999px;
    padding: 0
      calc(
        var(--ck-select-control-gutter) * var(--ck-control-gutter-pill-scaling)
      );
  }

  .selectControl:where([data-block]) {
    width: 100%;
  }

  .selectControl[data-variant="ghost"] {
    --ck-select-control-background-color: var(
      --color-fill-primary-transparent-hover
    );
    --ck-select-control-ring-offset: -1px;
  }

  .selectControl[data-variant="ghost"]::before {
    background-color: var(--ck-select-control-background-color);
    opacity: 0;
    transform: scale(var(--scale));
  }

  :is(
    .selectControl[data-variant="ghost"][aria-expanded="true"],
    .selectControl[data-variant="ghost"][data-state="open"]
  )::before {
    opacity: 0.6;
    transform: scale(1);
  }

  @media (hover: hover) and (pointer: fine) {
    .selectControl[data-variant="ghost"]:where(
        :not([data-disabled])
      ):hover::before {
      opacity: 1;
      transform: scale(1);
    }
  }

  .selectControl[data-variant="ghost"]:where(:not([data-disabled])):not(
      :has(button:active)
    ):active::before {
    --ck-select-control-background-color: var(
      --color-fill-primary-transparent-pressed
    );
    opacity: 1;
    transform: scale(var(--scale));
  }

  .selectControl[data-variant="ghost"]:where(:not([data-disabled])):not(
      :has(button:active)
    ):active::after {
    transform: scale(var(--scale));
  }

  .selectControl[data-variant="ghost"]:where(
      :not([data-disabled])
    )[data-invalid]::before {
    --ck-select-control-background-color: transparent;
    box-shadow: 0 0 0 1px var(--ck-field-border-color-invalid) inset;
    opacity: 1;
    transform: scale(1);
  }

  @media (hover: hover) and (pointer: fine) {
    .selectControl[data-variant="ghost"]:where(
        :not([data-disabled])
      )[data-invalid]:hover::before {
      --ck-select-control-background-color: var(
        --color-fill-primary-transparent-hover
      );
    }
  }

  .selectControl[data-variant="soft"] {
    --ck-select-control-background-color: var(--color-fill-primary-soft-alpha);
  }

  .selectControl[data-variant="soft"]::before {
    background-color: var(--ck-select-control-background-color);
  }

  :is(
    .selectControl[data-variant="soft"][aria-expanded="true"],
    .selectControl[data-variant="soft"][data-state="open"]
  )::before {
    --ck-select-control-background-color: var(
      --color-fill-primary-soft-alpha-hover
    );
  }

  @media (hover: hover) and (pointer: fine) {
    .selectControl[data-variant="soft"]:where(
        :not([data-disabled])
      ):hover::before {
      --ck-select-control-background-color: var(
        --color-fill-primary-soft-alpha-hover
      );
    }
  }

  .selectControl[data-variant="soft"]:where(:not([data-disabled])):not(
      :has(button:active)
    ):active::before {
    --ck-select-control-background-color: var(
      --color-fill-primary-soft-alpha-active
    );
  }

  .selectControl[data-variant="soft"]:where(:not([data-disabled])):not(
      :has(button:active)
    ):active::before,
  .selectControl[data-variant="soft"]:where(:not([data-disabled])):not(
      :has(button:active)
    ):active::after {
    transform: scale(var(--scale));
  }

  .selectControl[data-variant="soft"]:where(
      :not([data-disabled])
    )[data-invalid]::before {
    box-shadow: 0 0 0 1px var(--ck-field-border-color-invalid) inset;
  }

  .selectControl[data-variant="outline"] {
    --ck-select-control-border-color: var(--ck-field-outline-border-color);
    --ck-select-control-ring-offset: -1px;
  }

  .selectControl[data-variant="outline"]::before {
    box-shadow: 0 0 0 1px var(--ck-select-control-border-color) inset;
    background-color: transparent;
  }

  .selectControl[data-variant="outline"][aria-expanded="true"],
  .selectControl[data-variant="outline"][data-state="open"] {
    --ck-select-control-border-color: var(
      --ck-field-outline-border-color-hover
    );
  }

  @media (hover: hover) and (pointer: fine) {
    .selectControl[data-variant="outline"]:where(:not([data-disabled])):hover {
      --ck-select-control-border-color: var(
        --ck-field-outline-border-color-hover
      );
    }
  }

  .selectControl[data-variant="outline"]:where(:not([data-disabled])):not(
      :has(button:active)
    ):active::before,
  .selectControl[data-variant="outline"]:where(:not([data-disabled])):not(
      :has(button:active)
    ):active::after {
    transform: scale(var(--scale));
  }

  .selectControl[data-variant="outline"]:where(
      :not([data-disabled])
    )[data-invalid]::before {
    --ck-select-control-border-color: var(--ck-field-border-color-invalid);
  }

  .selectControl:where([data-invalid]) {
    --ck-action-ring-color: var(--color-ring-danger);
  }

  @media (hover: hover) and (pointer: fine) {
    .selectControl:not([data-disabled]):hover .clear,
    .selectControl:not([data-disabled]):hover .dropdownIcon {
      opacity: 1;
    }
  }

  .selectControl[data-selected="false"] {
    color: var(--ck-field-placeholder-text-color);
  }

  .selectControl[data-disabled][data-variant] {
    --ck-select-control-background-color: var(--color-fill-disabled);
    --ck-select-control-border-color: var(--color-stroke-disabled);
    color: var(--color-text-unavailable);
    cursor: not-allowed;
  }

  .selectControl[data-disabled][data-variant] .dropdownIcon {
    color: var(--color-text-unavailable);
  }

  .selectControl[data-disabled][data-variant]:active::before {
    transform: scale(1);
  }

  .trigger {
    text-align: start;
  }

  .transitionChild {
    display: block;
  }

  .triggerText {
    max-width: 100%;
    color: inherit;
    text-overflow: ellipsis;
    white-space: nowrap;
    flex: 1;
    position: relative;
    overflow: hidden;
