import { formatWithTokens } from "./format-tokens";
import type { FormatContext, WeekParts } from "./format-tokens";
import { Locale } from "./locale";
import { Zone } from "./zone";

/*
 * The part of Luxon (MIT) the date picker uses, rebuilt on Intl. The picker
 * takes and returns this DateTime in place of a Luxon DateTime. Time zones are the system zone, UTC, fixed offsets and IANA names.
 */

const MS_PER_MINUTE = 60_000;
const MS_PER_SECOND = 1000;
const MINUTES_PER_HOUR = 60;
const MS_PER_HOUR = 3_600_000;
const MS_PER_DAY = 86_400_000;
const MONTHS_PER_YEAR = 12;
const MONTHS_PER_QUARTER = 3;
const DAYS_PER_WEEK = 7;
const ISO_MIN_DAYS_IN_FIRST_WEEK = 4;
const ISO_FIRST_DAY = 1;
const ISO_WEEKDAY_OFFSET = 10;
const LONG_ISO_YEAR_WEEKS = 53;
const SHORT_ISO_YEAR_WEEKS = 52;
const THURSDAY = 4;
const WEDNESDAY = 3;
const SHORT_YEAR_LIMIT = 100;
const FEBRUARY = 2;
const LEAP_YEAR_DAYS = 29;
const COMMON_YEAR_DAYS = 28;
const DAYS_IN_YEAR = 365;
const DAYS_IN_LEAP_YEAR = 366;

export type DateTimeUnit =
  | "day"
  | "hour"
  | "millisecond"
  | "minute"
  | "month"
  | "quarter"
  | "second"
  | "week"
  | "year";

export interface DurationLike {
  days?: number;
  hours?: number;
  milliseconds?: number;
  minutes?: number;
  months?: number;
  quarters?: number;
  seconds?: number;
  weeks?: number;
  years?: number;
}

export interface DateTimeFields {
  day?: number;
  hour?: number;
  millisecond?: number;
  minute?: number;
  month?: number;
  second?: number;
  year: number;
}

type Fields = Required<DateTimeFields>;

export interface DateTimeOptions {
  locale?: string | null;
  zone?: Zone | string;
}

interface ZonePlan {
  instant: DateTime;
  replacesZoneName: boolean;
  timeZone: string | undefined;
}

const formatterCache = new Map<string, Intl.DateTimeFormat>();

/** One Intl.DateTimeFormat per locale and options. */
const cachedFormatter = (intl: string, options: Intl.DateTimeFormatOptions) => {
  const key = JSON.stringify([intl, options]);
  let formatter = formatterCache.get(key);

  if (formatter === undefined) {
    formatter = new Intl.DateTimeFormat(intl, options);
    formatterCache.set(key, formatter);
  }

  return formatter;
};

const validZones = new Map<string, boolean>();

const isValidTimeZone = (name: string) => {
  let valid = validZones.get(name);

  if (valid === undefined) {
    try {
      new Intl.DateTimeFormat("en-US", { timeZone: name }).format();
      valid = true;
    } catch {
      valid = false;
    }

    validZones.set(name, valid);
  }

  return valid;
};

/* ------------------------------------------------------------ calendar math */

const isLeapYear = (year: number) =>
  year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31] as const;

const daysInMonthOf = (year: number, month: number) => {
  const index =
    (((month - 1) % MONTHS_PER_YEAR) + MONTHS_PER_YEAR) % MONTHS_PER_YEAR;

  const adjustedYear = year + Math.floor((month - 1) / MONTHS_PER_YEAR);

  if (index === FEBRUARY - 1) {
    return isLeapYear(adjustedYear) ? LEAP_YEAR_DAYS : COMMON_YEAR_DAYS;
  }

  return DAYS_IN_MONTH[index] ?? DAYS_IN_MONTH[0];
};

const utcFromFields = (fields: Fields) => {
  const date = new Date(
    Date.UTC(
      fields.year,
      fields.month - 1,
      fields.day,
      fields.hour,
      fields.minute,
      fields.second,
      fields.millisecond
    )
  );

  // Date.UTC maps years 0..99 to 1900..1999.
  if (fields.year < SHORT_YEAR_LIMIT && fields.year >= 0) {
    date.setUTCFullYear(fields.year);
  }

  return date.getTime();
};

const fieldsFromUtc = (localTs: number): Fields => {
  const date = new Date(localTs);

  return {
    day: date.getUTCDate(),
    hour: date.getUTCHours(),
    millisecond: date.getUTCMilliseconds(),
    minute: date.getUTCMinutes(),
    month: date.getUTCMonth() + 1,
    second: date.getUTCSeconds(),
    year: date.getUTCFullYear(),
  };
};

/** Luxon `fixOffset`: the instant whose local time in `zone` is `localTs`. */
const instantFromLocal = (
  localTs: number,
  zone: Zone,
  offsetGuess: number
): number => {
  let utcGuess = localTs - offsetGuess * MS_PER_MINUTE;
  const second = zone.offset(utcGuess);

  if (offsetGuess === second) {
    return utcGuess;
  }

  utcGuess -= (second - offsetGuess) * MS_PER_MINUTE;
  const third = zone.offset(utcGuess);

  if (second === third) {
    return utcGuess;
  }

  return localTs - Math.min(second, third) * MS_PER_MINUTE;
};

/** A calendar day at UTC midnight; `Date.UTC` maps the years 0 to 99 to 19xx. */
const utcDay = (year: number, month: number, day: number) => {
  const date = new Date(Date.UTC(year, month - 1, day));

  if (year >= 0 && year < SHORT_YEAR_LIMIT) {
    date.setUTCFullYear(year, month - 1, day);
  }

  return date.getTime();
};

const weekdayOf = (year: number, month: number, day: number) =>
  new Date(utcDay(year, month, day)).getUTCDay() || DAYS_PER_WEEK;

const ordinalOf = (year: number, month: number, day: number) =>
  Math.round((utcDay(year, month, day) - utcDay(year, 1, 1)) / MS_PER_DAY) + 1;

const isoWeeksInYear = (year: number) => {
  const jan1 = new Date(Date.UTC(year, 0, 1)).getUTCDay();

  return jan1 === THURSDAY || (jan1 === WEDNESDAY && isLeapYear(year))
    ? LONG_ISO_YEAR_WEEKS
    : SHORT_ISO_YEAR_WEEKS;
};

const isoWeekParts = (fields: Fields): WeekParts => {
  const ordinal = ordinalOf(fields.year, fields.month, fields.day);
  const weekday = weekdayOf(fields.year, fields.month, fields.day);

  let weekNumber = Math.floor(
    (ordinal - weekday + ISO_WEEKDAY_OFFSET) / DAYS_PER_WEEK
  );

  let weekYear = fields.year;

  if (weekNumber < 1) {
    weekYear -= 1;
    weekNumber = isoWeeksInYear(weekYear);
  } else if (weekNumber > isoWeeksInYear(fields.year)) {
    weekYear += 1;
    weekNumber = 1;
  }

  return { ordinal, weekNumber, weekYear };
};

interface WeekInfo {
  firstDay: number;
  minimalDays: number;
}

/** Engines expose the week data as a method or a getter; the lib types lack both. */
type LocaleWithWeekInfo = Intl.Locale & {
  getWeekInfo?: () => Partial<WeekInfo>;
  weekInfo?: Partial<WeekInfo>;
};

/** Luxon's own fallback is Monday and four days when the engine has no data. */
const weekInfoOf = (locale: string): WeekInfo => {
  const intlLocale: LocaleWithWeekInfo = new Intl.Locale(locale);

  const info: Partial<WeekInfo> =
    intlLocale.getWeekInfo?.() ?? intlLocale.weekInfo ?? {};

  const { firstDay = ISO_FIRST_DAY, minimalDays = ISO_MIN_DAYS_IN_FIRST_WEEK } =
    info;

  return { firstDay, minimalDays };
};

/** An ISO weekday counted from the week's first day, 1 to 7. */
const weekdayFrom = (isoWeekday: number, firstDay: number) =>
  ((isoWeekday - firstDay + DAYS_PER_WEEK) % DAYS_PER_WEEK) + 1;

const weekYearShift = (year: number, info: WeekInfo) =>
  -weekdayFrom(weekdayOf(year, 1, info.minimalDays), info.firstDay) +
  info.minimalDays -
  1;

/** The number of weeks in a week-year. */
const localWeeksInYear = (year: number, info: WeekInfo) =>
  ((isLeapYear(year) ? DAYS_IN_LEAP_YEAR : DAYS_IN_YEAR) -
    weekYearShift(year, info) +
    weekYearShift(year + 1, info)) /
  DAYS_PER_WEEK;

/** Week info with the locale's first day and minimal days. */
const localWeekParts = (fields: Fields, locale: string): WeekParts => {
  const info = weekInfoOf(locale);
  const ordinal = ordinalOf(fields.year, fields.month, fields.day);

  const weekday = weekdayFrom(
    weekdayOf(fields.year, fields.month, fields.day),
    info.firstDay
  );

  let weekNumber = Math.floor(
    (ordinal - weekday + 2 * DAYS_PER_WEEK - info.minimalDays) / DAYS_PER_WEEK
  );

  let weekYear = fields.year;

  if (weekNumber < 1) {
    weekYear -= 1;
    weekNumber = localWeeksInYear(weekYear, info);
  } else if (weekNumber > localWeeksInYear(fields.year, info)) {
    weekYear += 1;
    weekNumber = 1;
  }

  return { ordinal, weekNumber, weekYear };
};

/* ---------------------------------------------------------------- DateTime */

const UNIT_ORDER = [
  "year",
  "quarter",
  "month",
  "week",
  "day",
  "hour",
  "minute",
  "second",
  "millisecond",
] as const satisfies readonly DateTimeUnit[];

const unitIndex = (unit: DateTimeUnit) => UNIT_ORDER.indexOf(unit);

const DURATION_KEY = {
  day: "days",
  hour: "hours",
  millisecond: "milliseconds",
  minute: "minutes",
  month: "months",
  quarter: "quarters",
  second: "seconds",
  week: "weeks",
  year: "years",
} as const satisfies Record<DateTimeUnit, keyof DurationLike>;

const DURATION_KEYS = Object.values(DURATION_KEY);

/** Luxon's default `toLocaleString` format, `DateTime.DATE_SHORT`. */
const DATE_SHORT = {
  day: "numeric",
  month: "numeric",
  year: "numeric",
} as const satisfies Intl.DateTimeFormatOptions;

const negate = (duration: DurationLike): DurationLike => {
  const negated: DurationLike = {};

  for (const key of DURATION_KEYS) {
    const amount = duration[key];

    if (amount !== undefined) {
      negated[key] = -amount;
    }
  }

  return negated;
};

/** An instant with a zone and an optional locale. */
export class DateTime {
  readonly ts: number;

  readonly zone: Zone;

  readonly localeName: string | null;

  private cachedFields: Fields | undefined;

  private constructor(ts: number, zone: Zone, locale: string | null) {
    this.ts = ts;
    this.zone = zone;
    this.localeName = locale;
  }

  static now(): DateTime {
    return new DateTime(Date.now(), Zone.system, null);
  }

  static fromMillis(ms: number, options: DateTimeOptions = {}): DateTime {
    return new DateTime(ms, Zone.from(options.zone), options.locale ?? null);
  }

  static fromJSDate(date: Date, options: DateTimeOptions = {}): DateTime {
    return DateTime.fromMillis(date.getTime(), options);
  }

  static fromObject(
    fields: DateTimeFields,
    options: DateTimeOptions = {}
  ): DateTime {
    const zone = Zone.from(options.zone);

    const full: Fields = {
      day: fields.day ?? 1,
      hour: fields.hour ?? 0,
      millisecond: fields.millisecond ?? 0,
      minute: fields.minute ?? 0,
      month: fields.month ?? 1,
      second: fields.second ?? 0,
      year: fields.year,
    };

    const local = utcFromFields(full);

    return new DateTime(
      instantFromLocal(local, zone, zone.offset(local)),
      zone,
      options.locale ?? null
    );
  }

  static isDateTime(value: unknown): value is DateTime {
    return value instanceof DateTime;
  }

  private get fields(): Fields {
    this.cachedFields ??= fieldsFromUtc(
      this.ts + this.zone.offset(this.ts) * MS_PER_MINUTE
    );

    return this.cachedFields;
  }

  get isValid(): boolean {
    return !Number.isNaN(this.ts);
  }

  /** Luxon `locale`: the specified locale, else the system's. */
  get locale(): string {
    return Locale.create(this.localeName, false).locale;
  }

  get year(): number {
    return this.fields.year;
  }

  get month(): number {
    return this.fields.month;
  }

  get day(): number {
    return this.fields.day;
  }

  get hour(): number {
    return this.fields.hour;
  }

  get minute(): number {
    return this.fields.minute;
  }

  get second(): number {
    return this.fields.second;
  }

  get millisecond(): number {
    return this.fields.millisecond;
  }

  /** 1 (Monday) to 7 (Sunday). */
  get weekday(): number {
    return weekdayOf(this.year, this.month, this.day);
  }

  get daysInMonth(): number {
    return daysInMonthOf(this.year, this.month);
  }

  get zoneName(): string {
    return this.zone.zoneName;
  }

  get offset(): number {
    return this.zone.offset(this.ts);
  }

  toMillis(): number {
    return this.ts;
  }

  valueOf(): number {
    return this.ts;
  }

  toJSDate(): Date {
    return new Date(this.ts);
  }

  setLocale(locale: string | null): DateTime {
    return new DateTime(this.ts, this.zone, locale);
  }

  setZone(
    zone: Zone | string,
    { keepLocalTime = false }: { keepLocalTime?: boolean } = {}
  ): DateTime {
    const next = Zone.from(zone);

    if (next.equals(this.zone)) {
      return this;
    }

    if (keepLocalTime) {
      return DateTime.fromObject(this.fields, {
        locale: this.localeName,
        zone: next,
      });
    }

    return new DateTime(this.ts, next, this.localeName);
  }

  private withFields(fields: Fields): DateTime {
    return new DateTime(
      instantFromLocal(utcFromFields(fields), this.zone, this.offset),
      this.zone,
      this.localeName
    );
  }

  plus(duration: DurationLike): DateTime {
    const { fields } = this;

    const months =
      (duration.months ?? 0) + (duration.quarters ?? 0) * MONTHS_PER_QUARTER;

    const monthIndex = fields.month + months - 1;

    const year =
      fields.year +
      (duration.years ?? 0) +
      Math.floor(monthIndex / MONTHS_PER_YEAR);

    const month =
      (((monthIndex % MONTHS_PER_YEAR) + MONTHS_PER_YEAR) % MONTHS_PER_YEAR) +
      1;

    const day =
      Math.min(daysInMonthOf(year, month), fields.day) +
      (duration.days ?? 0) +
      (duration.weeks ?? 0) * DAYS_PER_WEEK;

    const millisToAdd =
      (duration.hours ?? 0) * MS_PER_HOUR +
      (duration.minutes ?? 0) * MS_PER_MINUTE +
      (duration.seconds ?? 0) * MS_PER_SECOND +
      (duration.milliseconds ?? 0);

    const moved = this.withFields({ ...fields, day, month, year });

    return millisToAdd === 0
      ? moved
      : new DateTime(moved.ts + millisToAdd, this.zone, this.localeName);
  }

  minus(duration: DurationLike): DateTime {
    return this.plus(negate(duration));
  }

  startOf(unit: DateTimeUnit): DateTime {
    const index = unitIndex(unit);
    const fields = { ...this.fields };

    if (unit === "quarter") {
      fields.month =
        (Math.ceil(fields.month / MONTHS_PER_QUARTER) - 1) *
          MONTHS_PER_QUARTER +
        1;
    }

    if (unit === "year") {
      fields.month = 1;
    }

    if (index <= unitIndex("month")) {
      fields.day = 1;
    }

    if (index <= unitIndex("day")) {
      fields.hour = 0;
    }

    if (index <= unitIndex("hour")) {
      fields.minute = 0;
    }

    if (index <= unitIndex("minute")) {
      fields.second = 0;
    }

    if (index <= unitIndex("second")) {
      fields.millisecond = 0;
    }

    const base = this.withFields(fields);

    return unit === "week" ? base.minus({ days: this.weekday - 1 }) : base;
  }

  endOf(unit: DateTimeUnit): DateTime {
    return this.plus({ [DURATION_KEY[unit]]: 1 })
      .startOf(unit)
      .minus({ milliseconds: 1 });
  }

  /** Luxon `hasSame`: `other` falls in the same `unit` as this, in this zone. */
  hasSame(other: DateTime, unit: DateTimeUnit): boolean {
    const converted = this.setZone(other.zone, { keepLocalTime: true });

    return (
      converted.startOf(unit).ts <= other.ts &&
      other.ts <= converted.endOf(unit).ts
    );
  }

  /**
   * Luxon's `PolyDateFormatter`: Intl formats the instant in an
   * IANA zone or the system zone. A fixed offset uses `Etc/GMT` when Intl knows
   * that whole-hour zone. Otherwise the wall time is formatted as UTC and the
   * zone-name part is replaced by the fixed zone's own name ("UTC+5:30").
   */
  private formatIntlParts(
    intl: string,
    options: Intl.DateTimeFormatOptions
  ): Intl.DateTimeFormatPart[] {
    const plan: ZonePlan =
      options.timeZone === undefined
        ? this.zonePlan()
        : {
            instant: this,
            replacesZoneName: false,
            timeZone: options.timeZone,
          };

    const parts = cachedFormatter(intl, {
      ...options,
      timeZone: plan.timeZone,
    }).formatToParts(plan.instant.toJSDate());

    if (!plan.replacesZoneName) {
      return parts;
    }

    return parts.map((part) =>
      part.type === "timeZoneName"
        ? {
            ...part,
            value:
              this.zone.offsetName(
                plan.instant.ts,
                options.timeZoneName,
                intl
              ) ?? "",
          }
        : part
    );
  }

  /** Which instant and Intl zone `PolyDateFormatter` formats this DateTime in. */
  private zonePlan(): ZonePlan {
    if (this.zone.kind === "iana") {
      return {
        instant: this,
        replacesZoneName: false,
        timeZone: this.zone.name,
      };
    }

    if (this.zone.kind !== "fixed") {
      return { instant: this, replacesZoneName: false, timeZone: undefined };
    }

    const hours = -1 * (this.offset / MINUTES_PER_HOUR);
    const etc = hours >= 0 ? `Etc/GMT+${hours}` : `Etc/GMT${hours}`;

    if (this.offset !== 0 && isValidTimeZone(etc)) {
      return { instant: this, replacesZoneName: false, timeZone: etc };
    }

    return {
      instant:
        this.offset === 0
          ? this
          : this.setZone(Zone.utc).plus({ minutes: this.offset }),
      replacesZoneName: true,
      timeZone: "UTC",
    };
  }

  private formatIntl(
    intl: string,
    options: Intl.DateTimeFormatOptions
  ): string {
    return this.formatIntlParts(intl, options)
      .map(({ value }) => value)
      .join("");
  }

  /** Luxon `toLocaleString`: Intl formatting in this zone and locale. */
  toLocaleString(options?: Intl.DateTimeFormatOptions): string {
    return this.formatIntl(
      Locale.create(this.localeName, false).intl,
      options ?? DATE_SHORT
    );
  }

  private formatContext(): FormatContext {
    // Without a locale Luxon formats names in English (`redefaultToEN`), but
    // a macro token formats in the DateTime's own locale or the system's.
    const names = Locale.create(this.localeName, true);
    const system = Locale.create(this.localeName, false);
    const { fields } = this;

    return {
      day: fields.day,
      hasOtherCalendar: names.usesOtherCalendar,
      hour: fields.hour,
      isEnglish: names.usesEnglishNames,
      iso: isoWeekParts(fields),
      local: localWeekParts(fields, system.locale),
      macro: (options) => this.formatIntl(system.intl, options),
      millisecond: fields.millisecond,
      minute: fields.minute,
      month: fields.month,
      num: (value, padTo) => names.num(value, padTo),
      offset: (style) => this.zone.formatOffset(this.ts, style),
      offsetName: (style) => this.zone.offsetName(this.ts, style, names.locale),
      part: (options, type) =>
        this.formatIntlParts(names.intl, options).find(
          (entry) => entry.type.toLowerCase() === type.toLowerCase()
        )?.value ?? null,
      second: fields.second,
      ts: this.ts,
      weekday: this.weekday,
      year: fields.year,
      zoneName: this.zoneName,
    };
  }

  /** Luxon `toFormat`. */
  toFormat(format: string): string {
    return formatWithTokens(format, this.formatContext());
  }
}

/* ------------------------------------------------------------- picker helpers */

/** A DateTime or a JS Date becomes a DateTime; empty stays null. */
export const toDateTime = (
  value: DateTime | Date | null | undefined
): DateTime | null => {
  if (value === null || value === undefined) {
    return null;
  }

  return DateTime.isDateTime(value) ? value : DateTime.fromJSDate(value);
};

/** Both fall on the same day. */
export const isSameDay = (a: DateTime, b: DateTime) => a.hasSame(b, "day");

/** The day is today in the value's zone. */
export const isToday = (value: DateTime) =>
  isSameDay(value, DateTime.now().setZone(value.zone));

/** `a` is strictly before `b`. */
export const isBefore = (a: DateTime, b: DateTime | undefined) =>
  a.toMillis() < (b?.toMillis() ?? Number.NaN);

/** The start of every day of the month of `value`. */
export const daysOfMonth = (value: DateTime): DateTime[] => {
  const start = value.startOf("month");

  return Array.from({ length: start.daysInMonth }, (_, index) =>
    start.plus({ days: index }).startOf("day")
  );
};

/** Chunks of `size`. */
export const chunk = <T>(items: readonly T[], size = DAYS_PER_WEEK): T[][] => {
  const rows: T[][] = [];

  for (let index = 0; index < items.length; index += size) {
    rows.push(items.slice(index, index + size));
  }

  return rows;
};

/**
 * Luxon `Interval.fromDateTimes(start, end).contains(value)`: an interval whose
 * end is before its start is invalid and contains nothing. The end is
 * exclusive.
 */
export const intervalContains = (
  start: DateTime,
  end: DateTime,
  value: DateTime
) => end.ts >= start.ts && start.ts <= value.ts && end.ts > value.ts;

const SUNDAY_FIRST_LABELS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"] as const;
const SUNDAY_2024_01_07 = { day: 7, month: 1, year: 2024 } as const;

/** The weekday labels, Sunday first. */
export const weekdayLabels = (locale: string | undefined): string[] => {
  if (locale === undefined || locale === "") {
    return [...SUNDAY_FIRST_LABELS];
  }

  const sunday = DateTime.fromObject(SUNDAY_2024_01_07);

  return SUNDAY_FIRST_LABELS.map((_, index) =>
    sunday
      .plus({ days: index })
      .setLocale(locale)
      .toLocaleString({
        calendar: "gregory",
        weekday: locale.split("-")[0] === "ar" ? "narrow" : "short",
      })
  );
};

/** "MMMM yyyy" for the locale. */
export const monthLabel = (value: DateTime, locale: string | undefined) =>
  (locale === undefined || locale === ""
    ? value
    : value.setLocale(locale)
  ).toLocaleString({ calendar: "gregory", month: "long", year: "numeric" });

const QUOTED_TEXT = /'(?:[^']|'')*'/gu;

/** The Intl hour options for the hour tokens of a format. */
const hourOptions = (format: string): Intl.DateTimeFormatOptions => {
  if (format.includes("hh")) {
    return { hour: "2-digit", hour12: true };
  }

  if (format.includes("h")) {
    return { hour: "numeric", hour12: true };
  }

  if (format.includes("HH")) {
    return { hour: "2-digit", hour12: false };
  }

  return format.includes("H") ? { hour: "numeric", hour12: false } : {};
};

const monthOption = (format: string): Intl.DateTimeFormatOptions["month"] => {
  if (format.includes("MMMM")) {
    return "long";
  }

  if (format.includes("MMM")) {
    return "short";
  }

  if (format.includes("MM")) {
    return "2-digit";
  }

  return format.includes("M") ? "numeric" : undefined;
};

const numberOption = (
  format: string,
  two: string,
  one: string
): "2-digit" | "numeric" | undefined => {
  if (format.includes(two)) {
    return "2-digit";
  }

  return format.includes(one) ? "numeric" : undefined;
};

/** The Intl options that stand for a Luxon format string. */
const formatOptionsFor = (format: string): Intl.DateTimeFormatOptions => {
  const stripped = format.replaceAll(QUOTED_TEXT, "");

  const options: Intl.DateTimeFormatOptions = {
    calendar: "gregory",
    day: numberOption(stripped, "dd", "d"),
    minute: numberOption(stripped, "mm", "m"),
    month: monthOption(stripped),
    second: numberOption(stripped, "ss", "s"),
    ...hourOptions(stripped),
  };

  if (stripped.includes("y")) {
    options.year = stripped.includes("yyyy") ? "numeric" : "2-digit";
  }

  if (stripped.includes("a")) {
    options.hour12 = true;
  }

  if (stripped.includes("Z")) {
    options.timeZoneName = "shortOffset";
  }

  return options;
};

/** With a locale, Intl options; without, Luxon tokens. */
export const formatValue = (
  value: DateTime,
  format: string,
  locale: string | undefined
) =>
  locale === undefined || locale === ""
    ? value.toFormat(format)
    : value.setLocale(locale).toLocaleString(formatOptionsFor(format));

import type { OffsetStyle } from "./zone";

/*
 * Luxon's `Formatter.formatDateTimeFromString` as a table of tokens, and `Formatter.parseFormat`. A format string
 * splits into quoted or whitespace literals and runs of one letter; a run that
 * names no token is a macro token (`D`, `tt`, `ffff`, ...) or stays as typed.
 * `toFormat` never prints `Z` for UTC (that is `allowZ`, which only `toISO`
 * sets), and a name Intl cannot find prints as the text "null", as Luxon's
 * string concatenation does.
 */

const TWO_DIGITS = 2;
const THREE_DIGITS = 3;
const FOUR_DIGITS = 4;
const SIX_DIGITS = 6;
const MS_PER_SECOND = 1000;
const TEN_MS = 10;
const HUNDRED_MS = 100;
const MONTHS_PER_QUARTER = 3;
const TWELVE = 12;

type NameStyle = "long" | "narrow" | "short";

export interface WeekParts {
  ordinal: number;
  weekNumber: number;
  weekYear: number;
}

/** What a token reads from the DateTime being formatted. */
export interface FormatContext {
  /** The calendar fields in the DateTime's zone. */
  day: number;
  /** The locale's output calendar is not gregory (`outputCalendar`). */
  hasOtherCalendar: boolean;
  hour: number;
  iso: WeekParts;
  /** Names come from the English tables (`listingMode === "en"`). */
  isEnglish: boolean;
  local: WeekParts;
  /** Formats the macro token's Intl options in the system-default locale. */
  macro: (options: Intl.DateTimeFormatOptions) => string;
  millisecond: number;
  minute: number;
  month: number;
  /** Prints a number in the formatting locale, padded to `padTo` digits. */
  num: (value: number | string, padTo?: number) => string;
  offset: (style: OffsetStyle) => string;
  /** The zone's name in the formatting locale (`zone.offsetName`). */
  offsetName: (style: "long" | "short") => string | null;
  /** One Intl part of the DateTime in the formatting locale. */
  part: (
    options: Intl.DateTimeFormatOptions,
    type: Intl.DateTimeFormatPartTypes
  ) => string | null;
  second: number;
  ts: number;
  weekday: number;
  year: number;
  zoneName: string;
}

type TokenFormatter = (context: FormatContext) => string;

const MONTH_NAMES: Record<NameStyle, readonly string[]> = {
  long: [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ],
  narrow: ["J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N", "D"],
  short: [
    "Jan",
    "Feb",
    "Mar",
    "Apr",
    "May",
    "Jun",
    "Jul",
    "Aug",
    "Sep",
    "Oct",
    "Nov",
    "Dec",
  ],
};

const WEEKDAY_NAMES: Record<NameStyle, readonly string[]> = {
  long: [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
  ],
  narrow: ["M", "T", "W", "T", "F", "S", "S"],
  short: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
};

const ERA_NAMES: Record<NameStyle, readonly [string, string]> = {
  long: ["Before Christ", "Anno Domini"],
  narrow: ["B", "A"],
  short: ["BC", "AD"],
};

const lastTwo = (value: number) => String(value).slice(-TWO_DIGITS);

const hour12 = (context: FormatContext) =>
  context.hour % TWELVE === 0 ? TWELVE : context.hour % TWELVE;

interface CalendarField {
  options: Intl.DateTimeFormatOptions;
  type: Intl.DateTimeFormatPartTypes;
}

/**
 * A number token. In a locale whose calendar is not gregory, the day, month
 * and year tokens ask Intl for the field instead.
 */
const digits =
  (
    read: (context: FormatContext) => number | string,
    width = 0,
    calendar?: CalendarField
  ): TokenFormatter =>
  (context) =>
    calendar && context.hasOtherCalendar
      ? String(context.part(calendar.options, calendar.type))
      : context.num(read(context), width);

const month =
  (style: NameStyle, standalone: boolean): TokenFormatter =>
  (context) =>
    context.isEnglish
      ? (MONTH_NAMES[style][context.month - 1] ?? "")
      : String(
          context.part(
            standalone ? { month: style } : { day: "numeric", month: style },
            "month"
          )
        );

const weekday =
  (style: NameStyle, standalone: boolean): TokenFormatter =>
  (context) =>
    context.isEnglish
      ? (WEEKDAY_NAMES[style][context.weekday - 1] ?? "")
      : String(
          context.part(
            standalone
              ? { weekday: style }
              : { day: "numeric", month: "long", weekday: style },
            "weekday"
          )
        );

const era =
  (style: NameStyle): TokenFormatter =>
  (context) =>
    context.isEnglish
      ? ERA_NAMES[style][context.year < 0 ? 0 : 1]
      : String(context.part({ era: style }, "era"));

const dayPeriod: TokenFormatter = (context) =>
  context.isEnglish
    ? (["AM", "PM"][context.hour < TWELVE ? 0 : 1] ?? "")
    : String(context.part({ hour: "numeric", hourCycle: "h12" }, "dayPeriod"));

const zoneOffset =
  (style: OffsetStyle): TokenFormatter =>
  (context) =>
    context.offset(style);

const zoneName =
  (style: "long" | "short"): TokenFormatter =>
  (context) =>
    String(context.offsetName(style));

const DAY: CalendarField = { options: { day: "numeric" }, type: "day" };
const DAY_2: CalendarField = { options: { day: "2-digit" }, type: "day" };

const MONTH_ONLY: CalendarField = {
  options: { month: "numeric" },
  type: "month",
};

const MONTH_2: CalendarField = {
  options: { month: "2-digit" },
  type: "month",
};

const MONTH_DAY: CalendarField = {
  options: { day: "numeric", month: "numeric" },
  type: "month",
};

const MONTH_2_DAY: CalendarField = {
  options: { day: "numeric", month: "2-digit" },
  type: "month",
};

const YEAR: CalendarField = { options: { year: "numeric" }, type: "year" };
const YEAR_2: CalendarField = { options: { year: "2-digit" }, type: "year" };

const TOKENS = new Map<string, TokenFormatter>([
  ["S", digits((c) => c.millisecond)],
  ["u", digits((c) => c.millisecond, THREE_DIGITS)],
  ["SSS", digits((c) => c.millisecond, THREE_DIGITS)],
  ["s", digits((c) => c.second)],
  ["ss", digits((c) => c.second, TWO_DIGITS)],
  ["uu", digits((c) => Math.floor(c.millisecond / TEN_MS), TWO_DIGITS)],
  ["uuu", digits((c) => Math.floor(c.millisecond / HUNDRED_MS))],
  ["m", digits((c) => c.minute)],
  ["mm", digits((c) => c.minute, TWO_DIGITS)],
  ["h", digits(hour12)],
  ["hh", digits(hour12, TWO_DIGITS)],
  ["H", digits((c) => c.hour)],
  ["HH", digits((c) => c.hour, TWO_DIGITS)],
  ["Z", zoneOffset("narrow")],
  ["ZZ", zoneOffset("short")],
  ["ZZZ", zoneOffset("techie")],
  ["ZZZZ", zoneName("short")],
  ["ZZZZZ", zoneName("long")],
  ["z", (c) => c.zoneName],
  ["a", dayPeriod],
  ["d", digits((c) => c.day, 0, DAY)],
  ["dd", digits((c) => c.day, TWO_DIGITS, DAY_2)],
  ["c", digits((c) => c.weekday)],
  ["ccc", weekday("short", true)],
  ["cccc", weekday("long", true)],
  ["ccccc", weekday("narrow", true)],
  ["E", digits((c) => c.weekday)],
  ["EEE", weekday("short", false)],
  ["EEEE", weekday("long", false)],
  ["EEEEE", weekday("narrow", false)],
  ["L", digits((c) => c.month, 0, MONTH_DAY)],
  ["LL", digits((c) => c.month, TWO_DIGITS, MONTH_2_DAY)],
  ["LLL", month("short", true)],
  ["LLLL", month("long", true)],
  ["LLLLL", month("narrow", true)],
  ["M", digits((c) => c.month, 0, MONTH_ONLY)],
  ["MM", digits((c) => c.month, TWO_DIGITS, MONTH_2)],
  ["MMM", month("short", false)],
  ["MMMM", month("long", false)],
  ["MMMMM", month("narrow", false)],
  ["y", digits((c) => c.year, 0, YEAR)],
  ["yy", digits((c) => lastTwo(c.year), TWO_DIGITS, YEAR_2)],
  ["yyyy", digits((c) => c.year, FOUR_DIGITS, YEAR)],
  ["yyyyyy", digits((c) => c.year, SIX_DIGITS, YEAR)],
  ["G", era("short")],
  ["GG", era("long")],
  ["GGGGG", era("narrow")],
  ["kk", digits((c) => lastTwo(c.iso.weekYear), TWO_DIGITS)],
  ["kkkk", digits((c) => c.iso.weekYear, FOUR_DIGITS)],
  ["W", digits((c) => c.iso.weekNumber)],
  ["WW", digits((c) => c.iso.weekNumber, TWO_DIGITS)],
  ["n", digits((c) => c.local.weekNumber)],
  ["nn", digits((c) => c.local.weekNumber, TWO_DIGITS)],
  ["ii", digits((c) => lastTwo(c.local.weekYear), TWO_DIGITS)],
  ["iiii", digits((c) => c.local.weekYear, FOUR_DIGITS)],
  ["o", digits((c) => c.iso.ordinal)],
  ["ooo", digits((c) => c.iso.ordinal, THREE_DIGITS)],
  ["q", digits((c) => Math.ceil(c.month / MONTHS_PER_QUARTER))],
  ["qq", digits((c) => Math.ceil(c.month / MONTHS_PER_QUARTER), TWO_DIGITS)],
  ["X", digits((c) => Math.floor(c.ts / MS_PER_SECOND))],
  ["x", digits((c) => c.ts)],
]);

const DATE_SHORT = {
  day: "numeric",
  month: "numeric",
  year: "numeric",
} as const;

const DATE_MED = { day: "numeric", month: "short", year: "numeric" } as const;
const DATE_FULL = { day: "numeric", month: "long", year: "numeric" } as const;

const DATE_HUGE = {
  day: "numeric",
  month: "long",
  weekday: "long",
  year: "numeric",
} as const;

const TIME_SIMPLE = { hour: "numeric", minute: "numeric" } as const;
const TIME_SECONDS = { ...TIME_SIMPLE, second: "numeric" } as const;
const TIME_SHORT_OFFSET = { ...TIME_SECONDS, timeZoneName: "short" } as const;
const TIME_LONG_OFFSET = { ...TIME_SECONDS, timeZoneName: "long" } as const;
const H23 = { hourCycle: "h23" } as const;

/** Luxon's macro tokens (`Formatter.macroTokenToFormatOpts`). */
const MACRO_TOKENS = new Map<string, Intl.DateTimeFormatOptions>([
  ["D", DATE_SHORT],
  ["DD", DATE_MED],
  ["DDD", DATE_FULL],
  ["DDDD", DATE_HUGE],
  ["F", { ...DATE_SHORT, ...TIME_SECONDS }],
  ["FF", { ...DATE_MED, ...TIME_SECONDS }],
  ["FFF", { ...DATE_FULL, ...TIME_SHORT_OFFSET }],
  ["FFFF", { ...DATE_HUGE, ...TIME_LONG_OFFSET }],
  ["T", { ...TIME_SIMPLE, ...H23 }],
  ["TT", { ...TIME_SECONDS, ...H23 }],
  ["TTT", { ...TIME_SHORT_OFFSET, ...H23 }],
  ["TTTT", { ...TIME_LONG_OFFSET, ...H23 }],
  ["f", { ...DATE_SHORT, ...TIME_SIMPLE }],
  ["ff", { ...DATE_MED, ...TIME_SIMPLE }],
  ["fff", { ...DATE_FULL, ...TIME_SIMPLE, timeZoneName: "short" }],
  ["ffff", { ...DATE_HUGE, ...TIME_SIMPLE, timeZoneName: "long" }],
  ["t", TIME_SIMPLE],
  ["tt", TIME_SECONDS],
  ["ttt", TIME_SHORT_OFFSET],
  ["tttt", TIME_LONG_OFFSET],
]);

interface FormatPiece {
  literal: boolean;
  val: string;
}

const WHITESPACE_ONLY = /^\s+$/u;

/** Luxon `Formatter.parseFormat`: quoted text and whitespace are literals. */
const parseFormat = (format: string): FormatPiece[] => {
  const pieces: FormatPiece[] = [];
  let current: string | null = null;
  let currentFull = "";
  let bracketed = false;

  for (const char of format) {
    if (char === "'") {
      if (currentFull.length > 0 || bracketed) {
        pieces.push({
          literal: bracketed || WHITESPACE_ONLY.test(currentFull),
          val: currentFull === "" ? "'" : currentFull,
        });
      }

      current = null;
      currentFull = "";
      bracketed = !bracketed;
    } else if (bracketed || char === current) {
      currentFull += char;
    } else {
      if (currentFull.length > 0) {
        pieces.push({
          literal: WHITESPACE_ONLY.test(currentFull),
          val: currentFull,
        });
      }

      currentFull = char;
      current = char;
    }
  }

  if (currentFull.length > 0) {
    pieces.push({
      literal: bracketed || WHITESPACE_ONLY.test(currentFull),
      val: currentFull,
    });
  }

  return pieces;
};

const formatToken = (token: string, context: FormatContext): string => {
  const formatter = TOKENS.get(token);

  if (formatter) {
    return formatter(context);
  }

  const macro = MACRO_TOKENS.get(token);

  return macro ? context.macro(macro) : token;
};

/** Luxon `toFormat`. */
export const formatWithTokens = (format: string, context: FormatContext) =>
  parseFormat(format)
    .map((piece) =>
      piece.literal ? piece.val : formatToken(piece.val, context)
    )
    .join("");

/*
 * When the pointer leaves the trigger or content, the popover stays open
 * while the pointer moves through the convex hull of the exit point and the
 * other element's box.
 */

export interface Point {
  x: number;
  y: number;
}

type Side = "bottom" | "left" | "right" | "top";

const EXIT_PADDING = 5;

/** The side of the box nearest to the point. */
const nearestSide = (point: Point, rect: DOMRect): Side => {
  const top = Math.abs(rect.top - point.y);
  const bottom = Math.abs(rect.bottom - point.y);
  const right = Math.abs(rect.right - point.x);
  const left = Math.abs(rect.left - point.x);
  const nearest = Math.min(top, bottom, right, left);

  if (nearest === left) {
    return "left";
  }

  if (nearest === right) {
    return "right";
  }

  return nearest === top ? "top" : "bottom";
};

/** Two points padded around the exit point, on the far side. */
const exitPoints = (point: Point, side: Side): Point[] => {
  switch (side) {
    case "top": {
      return [
        { x: point.x - EXIT_PADDING, y: point.y + EXIT_PADDING },
        { x: point.x + EXIT_PADDING, y: point.y + EXIT_PADDING },
      ];
    }

    case "bottom": {
      return [
        { x: point.x - EXIT_PADDING, y: point.y - EXIT_PADDING },
        { x: point.x + EXIT_PADDING, y: point.y - EXIT_PADDING },
      ];
    }

    case "left": {
      return [
        { x: point.x + EXIT_PADDING, y: point.y - EXIT_PADDING },
        { x: point.x + EXIT_PADDING, y: point.y + EXIT_PADDING },
      ];
    }

    case "right": {
      return [
        { x: point.x - EXIT_PADDING, y: point.y - EXIT_PADDING },
        { x: point.x - EXIT_PADDING, y: point.y + EXIT_PADDING },
      ];
    }

    default: {
      return [];
    }
  }
};

/** The four corners of a box. */
const cornerPoints = ({ top, right, bottom, left }: DOMRect): Point[] => [
  { x: left, y: top },
  { x: right, y: top },
  { x: right, y: bottom },
  { x: left, y: bottom },
];

/** Whether the point lies inside the polygon (ray casting). */
export const isPointInPolygon = (
  { x, y }: Point,
  polygon: readonly Point[]
): boolean => {
  let inside = false;

  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i, i += 1) {
    const current = polygon[i];
    const previous = polygon[j];

    if (
      current !== undefined &&
      previous !== undefined &&
      current.y > y !== previous.y > y &&
      x <
        ((previous.x - current.x) * (y - current.y)) /
          (previous.y - current.y) +
          current.x
    ) {
      inside = !inside;
    }
  }

  return inside;
};

const crossBelow = (a: Point, b: Point, c: Point) =>
  (a.x - b.x) * (c.y - b.y) >= (a.y - b.y) * (c.x - b.x);

/** Andrew's monotone chain over points sorted by x then y. */
const monotoneChain = (points: readonly Point[]): Point[] => {
  if (points.length <= 1) {
    return [...points];
  }

  const upper: Point[] = [];

  for (const point of points) {
    while (upper.length >= 2) {
      const last = upper.at(-1);
      const beforeLast = upper.at(-2);

      if (
        last !== undefined &&
        beforeLast !== undefined &&
        crossBelow(last, beforeLast, point)
      ) {
        upper.pop();
      } else {
        break;
      }
    }

    upper.push(point);
  }

  upper.pop();

  const lower: Point[] = [];

  for (const point of points.toReversed()) {
    while (lower.length >= 2) {
      const last = lower.at(-1);
      const beforeLast = lower.at(-2);

      if (
        last !== undefined &&
        beforeLast !== undefined &&
        crossBelow(last, beforeLast, point)
      ) {
        lower.pop();
      } else {
        break;
      }
    }

    lower.push(point);
  }

  lower.pop();

  const [onlyUpper] = upper;
  const [onlyLower] = lower;

  if (
    upper.length === 1 &&
    lower.length === 1 &&
    onlyUpper !== undefined &&
    onlyLower !== undefined &&
    onlyUpper.x === onlyLower.x &&
    onlyUpper.y === onlyLower.y
  ) {
    return upper;
  }

  return [...upper, ...lower];
};

/** The convex hull of the points. */
const convexHull = (points: readonly Point[]): Point[] =>
  monotoneChain(
    points.toSorted((a, b) => {
      if (a.x !== b.x) {
        return a.x < b.x ? -1 : 1;
      }

      if (a.y === b.y) {
        return 0;
      }

      return a.y < b.y ? -1 : 1;
    })
  );

/**
 * The grace area when the pointer leaves `from` toward `to`, the
 * hull of the padded exit points and the box of `to`.
 */
export const graceArea = (event: PointerEvent, from: Element, to: Element) => {
  const point = { x: event.clientX, y: event.clientY };

  const exit = exitPoints(
    point,
    nearestSide(point, from.getBoundingClientRect())
  );

  return convexHull([...exit, ...cornerPoints(to.getBoundingClientRect())]);
};

import { pad, systemLocale } from "./zone";

/*
 * Luxon's `Locale`: the locale a DateTime was created with, the string handed to
 * Intl, whether names come from the English tables, and how numbers print.
 * Unspecified locales fall back to the system locale, or to en-US when the
 * formatter asks for `defaultToEN`.
 */

const ROUND_DIGITS = 3;

const resolvedOptionsCache = new Map<
  string,
  Intl.ResolvedDateTimeFormatOptions
>();

const resolvedOptions = (locale: string) => {
  let options = resolvedOptionsCache.get(locale);

  if (options === undefined) {
    options = new Intl.DateTimeFormat(locale).resolvedOptions();
    resolvedOptionsCache.set(locale, options);
  }

  return options;
};

interface ParsedLocale {
  calendar: string | null;
  locale: string;
  numberingSystem: string | null;
}

/** Drops `-x-` and reads the `-u-` extension through Intl. */
const parseLocaleString = (specifier: string): ParsedLocale => {
  const privateUse = specifier.indexOf("-x-");
  const base = privateUse === -1 ? specifier : specifier.slice(0, privateUse);
  const extension = base.indexOf("-u-");

  if (extension === -1) {
    return { calendar: null, locale: base, numberingSystem: null };
  }

  let options: Intl.ResolvedDateTimeFormatOptions;
  let locale = base;

  try {
    options = new Intl.DateTimeFormat(base).resolvedOptions();
  } catch {
    locale = base.slice(0, extension);
    options = new Intl.DateTimeFormat(locale).resolvedOptions();
  }

  return {
    calendar: options.calendar,
    locale,
    numberingSystem: options.numberingSystem,
  };
};

/** A set, non-empty string: what JavaScript's truthiness means for these. */
const isPresent = (value: string | null): value is string =>
  value !== null && value !== "";

const intlString = (
  locale: string,
  numberingSystem: string | null,
  calendar: string | null
) => {
  let intl = locale;

  if (isPresent(calendar) || isPresent(numberingSystem)) {
    if (!intl.includes("-u-")) {
      intl += "-u";
    }

    if (isPresent(calendar)) {
      intl += `-ca-${calendar}`;
    }

    if (isPresent(numberingSystem)) {
      intl += `-nu-${numberingSystem}`;
    }
  }

  return intl;
};

export class Locale {
  readonly calendar: string | null;

  /** The locale Intl is asked for, with any numbering and calendar. */
  readonly intl: string;

  readonly locale: string;

  readonly numberingSystem: string | null;

  /** The locale the DateTime was created with, if any. */
  readonly specified: string | null;

  private constructor(locale: string, specified: string | null) {
    const parsed = parseLocaleString(locale);

    this.locale = parsed.locale;
    this.numberingSystem = parsed.numberingSystem;
    this.calendar = parsed.calendar;
    this.specified = specified;
    this.intl = intlString(this.locale, this.numberingSystem, this.calendar);
  }

  static create(specified: string | null, defaultToEN: boolean): Locale {
    const named = isPresent(specified) ? specified : null;

    return new Locale(named ?? (defaultToEN ? "en-US" : systemLocale()), named);
  }

  /** Whether the locale is English, including a case-sensitive last test. */
  private get isEnglish(): boolean {
    return (
      this.locale === "en" ||
      this.locale.toLowerCase() === "en-us" ||
      resolvedOptions(this.intl).locale.startsWith("en-us")
    );
  }

  /** Names come from the English tables. */
  get usesEnglishNames(): boolean {
    return (
      this.isEnglish &&
      (this.numberingSystem === null || this.numberingSystem === "latn") &&
      (this.calendar === null || this.calendar === "gregory")
    );
  }

  /** An output calendar other than gregory. */
  get usesOtherCalendar(): boolean {
    return this.calendar !== null && this.calendar !== "gregory";
  }

  /** Plain Latin digits need no Intl.NumberFormat. */
  private get fastNumbers(): boolean {
    if (isPresent(this.numberingSystem) && this.numberingSystem !== "latn") {
      return false;
    }

    return (
      this.numberingSystem === "latn" ||
      this.locale === "" ||
      this.locale.startsWith("en") ||
      resolvedOptions(this.locale).numberingSystem === "latn"
    );
  }

  /** Number formatting, as `numberFormatter({ padTo }).format(value)`. */
  num(value: number | string, padTo = 0): string {
    if (this.fastNumbers) {
      const rounded =
        Math.round(Number(value) * 10 ** ROUND_DIGITS) / 10 ** ROUND_DIGITS;

      return pad(rounded, padTo);
    }

    return new Intl.NumberFormat(this.intl, {
      minimumIntegerDigits: padTo > 0 ? padTo : undefined,
      useGrouping: false,
    }).format(Number(value));
  }
}

import { createContext, use } from "react";
import type { RefObject } from "react";

/* Shared popover state for its parts and callers, including hover state and refs. */

const SIDES = ["bottom", "left", "right", "top"] as const;
const ALIGNS = ["center", "end", "start"] as const;

export type PopoverSide = (typeof SIDES)[number];

export type PopoverAlign = (typeof ALIGNS)[number];

export const isSide = (value: string): value is PopoverSide =>
  SIDES.some((side) => side === value);

export const isAlign = (value: string): value is PopoverAlign =>
  ALIGNS.some((align) => align === value);

export interface PopoverState {
  contentId: string;
  contentRef: RefObject<HTMLDivElement | null>;
  hoverOpenFocusTarget: RefObject<HTMLElement | null>;
  isPointerInTransitRef: RefObject<boolean>;
  onTriggerEnter: () => void;
  onTriggerLeave: () => void;
  open: boolean;
  setOpen: (next: boolean) => void;
  setShake: (next: boolean) => void;
  shake: boolean;
  showOnHover: boolean;
  temporarilyPreventClickToClose: boolean;
  triggerRef: RefObject<HTMLElement | null>;
}

export const PopoverContext = createContext<PopoverState | null>(null);

/** The popover's state, for the parts and for callers. */
export const usePopoverContext = (): PopoverState => {
  const state = use(PopoverContext);

  if (state === null) {
    throw new Error("Place popover parts under a Popover root");
  }

  return state;
};

import {
  autoUpdate,
  flip,
  hide,
  limitShift,
  offset,
  shift,
  size,
  useFloating,
} from "@floating-ui/react-dom";
import type { Middleware, Placement } from "@floating-ui/react-dom";
import { useLayoutEffect, useMemo } from "react";
import type { RefObject } from "react";

import { isAlign, isSide } from "./popover-context";
import type { PopoverAlign, PopoverSide } from "./popover-context";

/*
 * The floating-ui setup of the popover content, based on the Radix popper:
 * fixed strategy,
 * offset, shift with limitShift, flip, a size middleware that publishes the
 * available and anchor sizes, a transform origin from the placed side and
 * align, and hide when the anchor is detached.
 */

const NO_BOUNDARY: Element[] = [];

export const sideAndAlign = (placement: Placement) => {
  const [side = "", align = "center"] = placement.split("-");

  return [
    isSide(side) ? side : "bottom",
    isAlign(align) ? align : "center",
  ] as const;
};

const ALIGNMENTS = { center: "50%", end: "100%", start: "0%" } as const;

/** The Radix popper's `transformOrigin` middleware, without an arrow. */
const transformOrigin: Middleware = {
  fn({ placement, rects }) {
    const [side, align] = sideAndAlign(placement);
    const alignment = ALIGNMENTS[align];
    let x: string;
    let y: string;

    if (side === "bottom") {
      x = alignment;
      y = "0px";
    } else if (side === "top") {
      x = alignment;
      y = `${rects.floating.height}px`;
    } else if (side === "right") {
      x = "0px";
      y = alignment;
    } else {
      x = `${rects.floating.width}px`;
      y = alignment;
    }

    return { data: { x, y } };
  },
  name: "transformOrigin",
};

const isOrigin = (value: unknown): value is { x: string; y: string } =>
  typeof value === "object" &&
  value !== null &&
  "x" in value &&
  typeof value.x === "string" &&
  "y" in value &&
  typeof value.y === "string";

/** floating-ui's `roundByDPR`: the position snaps to device pixels. */
const roundByDpr = (value: number) => {
  const dpr = window.devicePixelRatio || 1;

  return Math.round(value * dpr) / dpr;
};

export interface PositionOptions {
  align: PopoverAlign;
  alignOffset: number;
  avoidCollisions: boolean;
  collisionPadding: number;
  hideWhenDetached: boolean;
  side: PopoverSide;
  sideOffset: number;
  sticky: "always" | "partial";
}

const buildMiddleware = (options: PositionOptions): Middleware[] => {
  const detectOverflow = {
    altBoundary: false,
    boundary: NO_BOUNDARY,
    padding: options.collisionPadding,
  };

  const middleware: Middleware[] = [
    offset({
      alignmentAxis: options.alignOffset,
      mainAxis: options.sideOffset,
    }),
  ];

  if (options.avoidCollisions) {
    middleware.push(
      shift({
        crossAxis: false,
        limiter: options.sticky === "partial" ? limitShift() : undefined,
        mainAxis: true,
        ...detectOverflow,
      }),
      flip({ ...detectOverflow })
    );
  }

  middleware.push(
    size({
      ...detectOverflow,
      apply({ availableHeight, availableWidth, elements, rects }) {
        const { style } = elements.floating;

        style.setProperty("--ck-flyout-available-width", `${availableWidth}px`);
        style.setProperty(
          "--ck-flyout-available-height",
          `${availableHeight}px`
        );
        style.setProperty(
          "--ck-flyout-anchor-width",
          `${rects.reference.width}px`
        );
        style.setProperty(
          "--ck-flyout-anchor-height",
          `${rects.reference.height}px`
        );
      },
    }),
    transformOrigin
  );

  if (options.hideWhenDetached) {
    middleware.push(hide({ strategy: "referenceHidden", ...detectOverflow }));
  }

  return middleware;
};

/**
 * Places the floating wrapper against the trigger (`triggerRef`). The wrapper
 * takes the content's z-index, as the Radix popper does.
 */
export const usePopoverPosition = (
  options: PositionOptions,
  triggerRef: RefObject<HTMLElement | null>,
  contentRef: RefObject<HTMLElement | null>
) => {
  const {
    align,
    alignOffset,
    avoidCollisions,
    collisionPadding,
    hideWhenDetached,
    side,
    sideOffset,
    sticky,
  } = options;

  const placement: Placement = align === "center" ? side : `${side}-${align}`;

  const middleware = useMemo(
    () =>
      buildMiddleware({
        align,
        alignOffset,
        avoidCollisions,
        collisionPadding,
        hideWhenDetached,
        side,
        sideOffset,
        sticky,
      }),
    [
      align,
      alignOffset,
      avoidCollisions,
      collisionPadding,
      hideWhenDetached,
      side,
      sideOffset,
      sticky,
    ]
  );

  const {
    isPositioned,
    middlewareData,
    placement: placed,
    refs: { floating: floatingRef, setFloating, setReference },
    x,
    y,
  } = useFloating({
    middleware,
    placement,
    strategy: "fixed",
    whileElementsMounted: autoUpdate,
  });

  useLayoutEffect(() => {
    setReference(triggerRef.current);
  }, [setReference, triggerRef]);

  useLayoutEffect(() => {
    const wrapper = floatingRef.current;
    const content = contentRef.current;

    if (wrapper && content) {
      wrapper.style.setProperty(
        "--ck-flyout-z-index",
        window.getComputedStyle(content).zIndex
      );
    }
  }, [floatingRef, contentRef]);

  const origin: unknown = middlewareData.transformOrigin;
  const [placedSide, placedAlign] = sideAndAlign(placed);

  return {
    hidden: middlewareData.hide?.referenceHidden === true,
    isPositioned,
    origin: isOrigin(origin) ? `${origin.x} ${origin.y}` : undefined,
    placedAlign,
    placedSide,
    setFloating,
    x: `${roundByDpr(x)}px`,
    y: `${roundByDpr(y)}px`,
  };
};

"use client";

import {
  AUTOFOCUS_ON_UNMOUNT,
  getTabbableCandidates,
  loopTabKey,
  useEscapeStack,
  useIsClient,
} from "@/components/dialog/dialog-layer";
import { usePortalContainer } from "@/components/platform-provider";
import {
  LayerEvent,
  noCleanup,
  useDismissableLayer,
  useLatest,
} from "@/lib/dismissable-layer";
import { cn } from "@/lib/utils";
import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import type {
  CSSProperties,
  KeyboardEvent,
  PointerEvent,
  ReactNode,
  SyntheticEvent,
} from "react";
import { createPortal } from "react-dom";

import { graceArea, isPointInPolygon } from "./hover-grace";
import type { Point } from "./hover-grace";
import { PopoverContext, usePopoverContext } from "./popover-context";
import type {
  PopoverAlign,
  PopoverSide,
  PopoverState,
