import styles from "./date-picker.module.css";

export type { PopoverAlign, PopoverSide } from "./popover-context";

/*
 * The date picker uses a vendored Radix non-modal popover. The content is not dismissed by Escape in
 * the layer (`onEscapeKeyDown` is prevented) but by the shared Escape stack. A
 * press outside is deferred until its click (the layer's
 * `deferPointerDownOutside`, here the shared `useDismissableLayer`), and a
 * press or focus outside dismisses unless it lands on the trigger. Focus
 * returns to the trigger on unmount unless the user interacted outside. The
 * shared options the date picker does not set are supported too: `showOnHover`
 * with its grace area, `shake`, `translucent`, and the content's width,
 * collision and focus options. There are no Anchor and Arrow parts.
 */

const DEFAULT_HOVER_OPEN_DELAY = 160;
const CLICK_GUARD_MS = 480;
const HOVER_BLUR_MS = 60;

export interface PopoverProps {
  children?: ReactNode;
  /** Milliseconds the pointer rests on the trigger before it opens. */
  hoverOpenDelay?: number;
  /** Called with the new state and the trigger element. */
  onOpenChange?: (open: boolean, trigger: HTMLElement | null) => void;
  /** The open state, when the caller owns it. */
  open?: boolean;
  /** Open while the pointer or focus is on the trigger. */
  showOnHover?: boolean;
}

export const Popover = ({
  children,
  hoverOpenDelay = DEFAULT_HOVER_OPEN_DELAY,
  onOpenChange,
  open: openProp,
  showOnHover = false,
}: PopoverProps) => {
  const [uncontrolled, setUncontrolled] = useState(false);
  const [shake, setShake] = useState(false);

  const [temporarilyPreventClickToClose, setTemporarilyPreventClickToClose] =
    useState(false);

  const open = openProp ?? uncontrolled;
  const hoverTimer = useRef<number | undefined>(undefined);
  const hoverOpenFocusTarget = useRef<HTMLElement | null>(null);
  const isPointerInTransitRef = useRef(false);
  const triggerRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);
  const contentId = useId();
  const latest = useLatest({ onOpenChange, open, showOnHover });

  /* After a hover open the trigger ignores a click for the click guard interval. */
  useEffect(() => {
    if (!temporarilyPreventClickToClose) {
      return noCleanup;
    }

    const timer = window.setTimeout(() => {
      setTemporarilyPreventClickToClose(false);
    }, CLICK_GUARD_MS);

    return () => {
      window.clearTimeout(timer);
    };
  }, [temporarilyPreventClickToClose]);

  const setOpen = useCallback(
    (next: boolean) => {
      window.clearTimeout(hoverTimer.current);
      const { current } = latest;

      if (current.open === next) {
        return;
      }

      if (!next) {
        setShake(false);

        if (current.showOnHover) {
          hoverOpenFocusTarget.current?.focus();
        }

        hoverOpenFocusTarget.current = null;
      }

      current.onOpenChange?.(next, triggerRef.current);
      setUncontrolled(next);

      if (current.showOnHover) {
        setTemporarilyPreventClickToClose(next);
      }
    },
    [latest]
  );

  const onTriggerEnter = useCallback(() => {
    hoverTimer.current = window.setTimeout(() => {
      setOpen(true);
    }, hoverOpenDelay);
  }, [hoverOpenDelay, setOpen]);

  const onTriggerLeave = useCallback(() => {
    window.clearTimeout(hoverTimer.current);
  }, []);

  useEffect(
    () => () => {
      window.clearTimeout(hoverTimer.current);
    },
    []
  );

  const state = useMemo<PopoverState>(
    () => ({
      contentId,
      contentRef,
      hoverOpenFocusTarget,
      isPointerInTransitRef,
      onTriggerEnter,
      onTriggerLeave,
      open,
      setOpen,
      setShake,
      shake,
      showOnHover,
      temporarilyPreventClickToClose,
      triggerRef,
    }),
    [
      contentId,
      onTriggerEnter,
      onTriggerLeave,
      open,
      setOpen,
      shake,
      showOnHover,
      temporarilyPreventClickToClose,
    ]
  );

  return <PopoverContext value={state}>{children}</PopoverContext>;
};

interface TriggerHandlers {
  onClick?: (event: SyntheticEvent<HTMLElement>) => void;
  onPointerDown?: (event: SyntheticEvent<HTMLElement>) => void;
}

/**
 * Right after a hover open a press on the trigger is swallowed, so
 * the click that follows the hover does not close the popover. A link is
 * never swallowed.
 */
const guardPress = (event: SyntheticEvent<HTMLElement>, prevent: boolean) => {
  const anchor =
    event.target instanceof Element ? event.target.closest("a[href]") : null;

  const isLink =
    event.currentTarget.nodeName.toLocaleLowerCase() === "a" ||
    (anchor !== null && event.currentTarget.contains(anchor));

  if (!isLink && prevent) {
    event.preventDefault();
    event.stopPropagation();
  }
};

interface HoverTriggerProps {
  onBlur?: () => void;
  onFocus?: () => void;
  onPointerLeave?: () => void;
  onPointerMove?: (event: PointerEvent<HTMLElement>) => void;
}

/** The trigger hover and focus handlers, set only with `showOnHover`. */
const useHoverTriggerProps = (): HoverTriggerProps => {
  const {
    contentRef,
    isPointerInTransitRef,
    onTriggerEnter,
    onTriggerLeave,
    setOpen,
    showOnHover,
  } = usePopoverContext();

  const hovering = useRef(false);

  if (!showOnHover) {
    return {};
  }

  return {
    onBlur: () => {
      window.setTimeout(() => {
        if (contentRef.current?.contains(document.activeElement) !== true) {
          setOpen(false);
        }
      }, HOVER_BLUR_MS);
    },
    onFocus: () => {
      setOpen(true);
    },
    onPointerLeave: () => {
      if (hovering.current) {
        onTriggerLeave();
        hovering.current = false;
      }
    },
    onPointerMove: (event) => {
      if (
        event.pointerType !== "touch" &&
        !hovering.current &&
        !isPointerInTransitRef.current
      ) {
        onTriggerEnter();
        hovering.current = true;
      }
    },
  };
};

/**
 * The props the trigger adds to the element they wrap
 * (`asChild`): the anchor ref, the dialog semantics, the toggle, the click
 * guard after a hover open and, with `showOnHover`, the hover and focus
 * handlers. The toggle is skipped when a handler prevented the default.
 */
export const usePopoverTrigger = ({
  onClick,
  onPointerDown,
}: TriggerHandlers = {}) => {
  const {
    contentId,
    open,
    setOpen,
    temporarilyPreventClickToClose,
    triggerRef,
  } = usePopoverContext();

  const hover = useHoverTriggerProps();

  /* A callback ref, so the trigger can be any element type. */
  const setTrigger = useCallback(
    (node: HTMLElement | null) => {
      triggerRef.current = node;

      return () => {
        triggerRef.current = null;
      };
    },
    [triggerRef]
  );

  return {
    "aria-controls": open ? contentId : undefined,
    "aria-expanded": open,
    "aria-haspopup": "dialog",
    "data-state": open ? "open" : "closed",
    ...hover,
    onClick: (event: SyntheticEvent<HTMLElement>) => {
      guardPress(event, temporarilyPreventClickToClose);
      onClick?.(event);

      if (!event.defaultPrevented) {
        setOpen(!open);
      }
    },
    onPointerDown: (event: SyntheticEvent<HTMLElement>) => {
      guardPress(event, temporarilyPreventClickToClose);
      onPointerDown?.(event);
    },
    ref: setTrigger,
  } as const;
};

/** Closes the popover. */
export const useClosePopover = () => {
  const { setOpen } = usePopoverContext();

  return useCallback(() => {
    setOpen(false);
  }, [setOpen]);
};

const COLLISION_PADDING = 20;
const DEFAULT_SIDE_OFFSET = 8;

const preventDefault = (event: LayerEvent | globalThis.KeyboardEvent) => {
  event.preventDefault();
};

export interface PopoverContentProps {
  align?: PopoverAlign;
  alignOffset?: number;
  "aria-label"?: string;
  /** Radix `avoidCollisions`: shift and flip to stay inside the window. */
  avoidCollisions?: boolean;
  /** Take focus when the content mounts (not for a hover popover). */
  autoFocus?: boolean;
  children?: ReactNode;
  className?: string;
  /** Radix `collisionPadding`, in pixels on every side. */
  collisionPadding?: number;
  dir?: "ltr" | "rtl";
  /** Radix `hideWhenDetached`: hide when the trigger scrolls out of view. */
  hideWhenDetached?: boolean;
  maxWidth?: number;
  minWidth?: number;
  /** Runs on unmount; `preventDefault` stops focus returning to the trigger. */
  onCloseAutoFocus?: (event: LayerEvent) => void;
  /** Keep the popover open when focus moves outside it. */
  preventCloseOnFocusOutside?: boolean;
  side?: PopoverSide;
  sideOffset?: number;
  /** Radix `sticky`: `always` stops the shift limiter. */
  sticky?: "always" | "partial";
  /** A blurred, translucent surface. */
  translucent?: boolean;
  width?: number;
}

/**
 * The content defaults: `alignOffset` is 0 only when
 * `align` is given as "center"; without `align` it is -5.
 */
const resolveContentProps = (props: PopoverContentProps) => ({
  align: props.align ?? "center",
  alignOffset: props.alignOffset ?? (props.align === "center" ? 0 : -5),
  autoFocus: props.autoFocus ?? true,
  avoidCollisions: props.avoidCollisions ?? true,
  collisionPadding: props.collisionPadding ?? COLLISION_PADDING,
  hideWhenDetached: props.hideWhenDetached ?? true,
  preventCloseOnFocusOutside: props.preventCloseOnFocusOutside ?? false,
  side: props.side ?? "bottom",
  sideOffset: props.sideOffset ?? DEFAULT_SIDE_OFFSET,
  sticky: props.sticky ?? "partial",
  translucent: props.translucent ?? false,
});

/**
 * Radix `PopoverContentNonModal` on the shared dismissable layer: remember an
 * outside interaction, and never dismiss for a press or focus on the trigger,
 * or for focus that follows an outside press.
 */
const useOutsideDismissal = (preventCloseOnFocusOutside: boolean) => {
  const { setOpen, triggerRef } = usePopoverContext();
  const hasInteractedOutside = useRef(false);
  const hasPointerDownOutside = useRef(false);

  const layer = useDismissableLayer({
    active: true,
    modal: false,
    onDismiss: () => {
      setOpen(false);
    },
    onEscapeKeyDown: preventDefault,
    onFocusOutside: preventCloseOnFocusOutside ? preventDefault : undefined,
    onInteractOutside: (event) => {
      const original = event.detail?.originalEvent;

      if (!event.defaultPrevented) {
        hasInteractedOutside.current = true;

        if (original?.type === "pointerdown") {
          hasPointerDownOutside.current = true;
        }
      }

      const { target } = event;

      if (
        target instanceof Node &&
        triggerRef.current?.contains(target) === true
      ) {
        event.preventDefault();
      }

      if (original?.type === "focusin" && hasPointerDownOutside.current) {
        event.preventDefault();
      }
    },
  });

  return { hasInteractedOutside, layer };
};

/** The content takes focus when it mounts. */
const useFocusOnMount = (enabled: boolean) => {
  const { contentRef } = usePopoverContext();

  useEffect(() => {
    const element = contentRef.current;

    if (element && enabled && !element.contains(document.activeElement)) {
      element.focus({ preventScroll: true });
    }
  }, [contentRef, enabled]);
};

/**
 * The focus scope's unmount focus: the content's `onCloseAutoFocus` runs in a
 * timeout after the unmount and a remount cancels it. Unless it prevents the
 * default, or the user interacted outside, focus returns to the trigger. A
 * hover popover prevents it by default.
 */
const useFocusReturn = (
  onCloseAutoFocus: ((event: LayerEvent) => void) | undefined,
  hasInteractedOutside: { current: boolean }
) => {
  const { showOnHover, triggerRef } = usePopoverContext();
  const latestClose = useLatest(onCloseAutoFocus);
  const timer = useRef<number | undefined>(undefined);

  const cancelFocusReturn = useCallback(() => {
    window.clearTimeout(timer.current);
  }, []);

  const scheduleFocusReturn = useCallback(() => {
    timer.current = window.setTimeout(() => {
      const event = new LayerEvent(AUTOFOCUS_ON_UNMOUNT);

      if (latestClose.current) {
        latestClose.current(event);
      } else if (showOnHover) {
        event.preventDefault();
      }

      if (!event.defaultPrevented && !hasInteractedOutside.current) {
        triggerRef.current?.focus();
      }
    }, 0);
  }, [hasInteractedOutside, latestClose, showOnHover, triggerRef]);

  useEffect(() => {
    cancelFocusReturn();

    return scheduleFocusReturn;
  }, [cancelFocusReturn, scheduleFocusReturn]);
};

/** Shift+Tab on the content itself moves to the last tabbable. */
const useContentKeyDown = () => {
  const { contentRef } = usePopoverContext();

  return (event: KeyboardEvent<HTMLDivElement>) => {
    const element = contentRef.current;

    if (
      element &&
      event.target === element &&
      event.key === "Tab" &&
      event.shiftKey
    ) {
      event.preventDefault();
      event.stopPropagation();
      getTabbableCandidates(element).at(-1)?.focus();

      return;
    }

    loopTabKey(event);
  };
};

const PopoverContentImpl = (props: PopoverContentProps) => {
  const options = resolveContentProps(props);

  const { contentId, contentRef, open, shake, showOnHover, triggerRef } =
    usePopoverContext();

  const {
    hidden,
    isPositioned,
    origin,
    placedAlign,
    placedSide,
    setFloating,
    x,
    y,
  } = usePopoverPosition(options, triggerRef, contentRef);

  const { hasInteractedOutside, layer } = useOutsideDismissal(
    options.preventCloseOnFocusOutside
  );

  useFocusOnMount(options.autoFocus && !showOnHover);
  useFocusReturn(props.onCloseAutoFocus, hasInteractedOutside);
  const handleKeyDown = useContentKeyDown();

  const setContentRef = useCallback(
    (node: HTMLDivElement | null) => {
      contentRef.current = node;

      return () => {
        contentRef.current = null;
      };
    },
    [contentRef]
  );

  // oxlint-disable-next-line anti-slop/require-safety-comment-for-type-assertion, typescript/no-unsafe-type-assertion -- SAFETY: every key is a `--name` custom property with a string value, which CSSProperties accepts
  const wrapperStyle = {
    "--ck-flyout-transform-origin": origin,
    "--ck-flyout-x": x,
    "--ck-flyout-y": y,
  } as CSSProperties;

  const { maxWidth, minWidth, width } = props;

  // oxlint-disable-next-line anti-slop/require-safety-comment-for-type-assertion, typescript/no-unsafe-type-assertion -- SAFETY: every key is a `--name` custom property with a string value, which CSSProperties accepts
  const contentStyle = {
    "--ck-flyout-max-width":
      maxWidth === undefined ? undefined : `${maxWidth}px`,
    "--ck-flyout-min-width":
      minWidth === undefined ? undefined : `${minWidth}px`,
    "--ck-flyout-pointer-events": layer.style?.pointerEvents,
    "--ck-flyout-width": width === undefined ? undefined : `${width}px`,
  } as CSSProperties;

  return (
    <div
      className={styles.popperWrapper}
      data-hidden={hidden ? "" : undefined}
      data-positioned={isPositioned}
      dir={props.dir}
      ref={setFloating}
      style={wrapperStyle}
    >
      {/* oxlint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- the layer tracks pointer and focus inside the content and loops Tab, as the Radix content does */}
      <div
        aria-label={props["aria-label"]}
        className={cn(styles.popover, props.className)}
        data-align={placedAlign}
        data-animate={shake ? "shake" : undefined}
        data-side={placedSide}
        data-state={open ? "open" : "closed"}
        data-translucent={options.translucent ? "true" : undefined}
        dir={props.dir}
        id={contentId}
        onBlurCapture={layer.handleBlurCapture}
        onFocusCapture={layer.handleFocusCapture}
        onKeyDown={handleKeyDown}
        onPointerDownCapture={layer.handlePointerDownCapture}
        ref={setContentRef}
        // oxlint-disable-next-line jsx-a11y/prefer-tag-over-role -- the popover content is a div with role dialog (Radix), not a modal dialog element
        role="dialog"
        style={contentStyle}
        tabIndex={-1}
      >
        {props.children}
      </div>
    </div>
  );
};

/** The content pointer tracking: the grace area between trigger and content. */
const useHoverGraceArea = () => {
  const { contentRef, isPointerInTransitRef, setOpen, triggerRef } =
    usePopoverContext();

  const [polygon, setPolygon] = useState<Point[] | null>(null);

  const clear = useCallback(() => {
    setPolygon(null);
    isPointerInTransitRef.current = false;
  }, [isPointerInTransitRef]);

  const start = useCallback(
    (event: globalThis.PointerEvent, from: Element, to: Element) => {
      setPolygon(graceArea(event, from, to));
      isPointerInTransitRef.current = true;
    },
    [isPointerInTransitRef]
  );

  useEffect(() => clear, [clear]);

  useEffect(() => {
    const trigger = triggerRef.current;
    const content = contentRef.current;

    if (!trigger || !content) {
      return noCleanup;
    }

    const onTriggerLeave = (event: globalThis.PointerEvent) => {
      start(event, trigger, content);
    };

    const onContentLeave = (event: globalThis.PointerEvent) => {
      start(event, content, trigger);
    };

    trigger.addEventListener("pointerleave", onTriggerLeave);
    content.addEventListener("pointerleave", onContentLeave);

    return () => {
      trigger.removeEventListener("pointerleave", onTriggerLeave);
      content.removeEventListener("pointerleave", onContentLeave);
    };
  }, [contentRef, start, triggerRef]);

  useEffect(() => {
    if (!polygon) {
      return noCleanup;
    }

    const onPointerMove = (event: globalThis.PointerEvent) => {
      const { target } = event;

      if (!(target instanceof Element)) {
        return;
      }

      const onElements =
        triggerRef.current?.contains(target) === true ||
        contentRef.current?.contains(target) === true;

      const outside = !isPointInPolygon(
        { x: event.clientX, y: event.clientY },
        polygon
      );

      if (onElements) {
        clear();
      } else if (outside || target.hasAttribute("aria-haspopup")) {
        clear();
        setOpen(false);
      }
    };

    document.addEventListener("pointermove", onPointerMove);

    return () => {
      document.removeEventListener("pointermove", onPointerMove);
    };
  }, [clear, contentRef, polygon, setOpen, triggerRef]);
};

/** The content Tab handler: Tab from the trigger moves into the content. */
const useHoverTabIntoContent = () => {
  const { contentRef, hoverOpenFocusTarget, triggerRef } = usePopoverContext();

  useEffect(() => {
    const onKeyDown = (event: globalThis.KeyboardEvent) => {
      const content = contentRef.current;

      if (!content || event.key !== "Tab" || event.shiftKey) {
        return;
      }

      const [first] = getTabbableCandidates(content);

      if (first === undefined) {
        return;
      }

      event.preventDefault();
      const active = document.activeElement;
      const trigger = triggerRef.current;
      const [triggerFirst] = trigger ? getTabbableCandidates(trigger) : [];

      if (active instanceof HTMLElement && trigger?.contains(active) === true) {
        hoverOpenFocusTarget.current = active;
      } else {
        hoverOpenFocusTarget.current =
          triggerFirst instanceof HTMLElement ? triggerFirst : trigger;
      }

      first.focus();
      document.removeEventListener("keydown", onKeyDown);
    };

    document.addEventListener("keydown", onKeyDown);

    return () => {
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [contentRef, hoverOpenFocusTarget, triggerRef]);
};

/**
 * The content of a hover popover. The pointer may cross from the
 * trigger to the content (and back) through a grace area; leaving it closes
 * the popover. Tab from the trigger moves into the content.
 */
const HoverPopoverContent = (props: PopoverContentProps) => {
  useHoverGraceArea();
  useHoverTabIntoContent();

  return <PopoverContentImpl {...props} />;
};

/**
 * The content portals to the platform container or the body and
 * mounts through a TransitionGroup with a 600 ms enter and a 300 ms exit.
 */
export const PopoverContent = (props: PopoverContentProps) => {
  const { open, setOpen, showOnHover } = usePopoverContext();
  const container = usePortalContainer();
  const isClient = useIsClient();

  useEscapeStack(open, () => {
    setOpen(false);
  });

  if (!isClient) {
    return null;
  }

  let content: ReactNode = null;

  if (open) {
    content = showOnHover ? (
      <HoverPopoverContent key="popover-hover" {...props} />
    ) : (
      <PopoverContentImpl key="popover" {...props} />
    );
  }

  return createPortal(
    <TransitionGroup
      className={styles.transition}
      enterDuration={600}
      exitDuration={300}
    >
      {content}
    </TransitionGroup>,
    container ?? document.body
  );
};

"use client";

import {
  DataButton,
  LoadingIndicator,
} from "@/components/button/data-button";
import { mergeRefs } from "@/components/dialog/dialog-layer";
import { cn } from "@/lib/utils";
import {
  ChevronDown as LucideChevronDown,
  ChevronsUpDown as LucideChevronsUpDown,
  CircleX as LucideCircleX,
} from "lucide-react";
import { useRef } from "react";
import type {
  ComponentType,
  KeyboardEvent,
  PointerEvent,
  ReactNode,
  Ref,
  RefObject,
} from "react";

import styles from "./date-picker.module.css";

/*
 * The trigger the date picker renders: SelectControl. It is a span with role button. It opens on pointer down
 * (not the right button) and on ArrowDown, ArrowUp and Space, which dispatch a
 * pointer down; Enter does nothing. `onInteract` replaces that: a press (not
 * the right button) and those keys call it instead, and the press is
 * prevented. `loading` swaps the clear button and dropdown icon for a spinner,
 * sets aria-busy and turns the pointer and key handling off. `opticallyAlign`
 * moves the control out by its gutter at the start or end.
 */

export type SelectControlVariant = "ghost" | "outline" | "soft";

export type SelectControlSize =
  | "2xl"
  | "2xs"
  | "3xl"
  | "3xs"
  | "lg"
  | "md"
  | "sm"
  | "xl"
  | "xs";

export type DropdownIconType = "chevronDown" | "dropdown" | "none";

/** The pressed scale grows with the width. */
export const setPressableScale = (event: PointerEvent<HTMLElement>) => {
  const target = event.currentTarget;
  const { offsetWidth } = target;
  let ratio = 0.98;

  if (offsetWidth <= 80) {
    ratio = 0.95;
  } else if (offsetWidth <= 150) {
    ratio = 0.965;
  } else if (offsetWidth <= 220) {
    ratio = 0.975;
  } else if (offsetWidth > 600) {
    ratio = 0.99;
  }

  target.style.setProperty("--scale", String(ratio));
};

const ClearIcon = () => (
  <LucideCircleX
    aria-hidden="true"
    height="1em"
    width="1em"
    strokeWidth={1.5}
  />
);

const ChevronDownIcon = ({ className }: { className: string }) => (
  <LucideChevronDown
    aria-hidden="true"
    className={className}
    height="1em"
    width="1em"
    viewBox="4 7 16 10"
    strokeWidth={1.5}
  />
);

const UpDownIcon = ({ className }: { className: string }) => (
  <LucideChevronsUpDown
    aria-hidden="true"
    className={className}
    height="1em"
    width="1em"
    viewBox="5 2 14 20"
    strokeWidth={1.5}
  />
);

const DropdownIcon = ({ iconType }: { iconType: DropdownIconType }) =>
  iconType === "chevronDown" ? (
    <ChevronDownIcon
      className={cn(styles.dropdownIcon, styles.dropdownIconChevron)}
    />
  ) : (
    <UpDownIcon className={styles.dropdownIcon} />
  );

export interface SelectControlProps extends Omit<
  React.ComponentProps<"span">,
  "onClick" | "ref"
> {
  block?: boolean;
  children?: ReactNode;
  /** The label of the clear button. */
  clearLabel?: string;
  disabled?: boolean;
  disablePressable?: boolean;
  dropdownIconType?: DropdownIconType;
  invalid?: boolean;
  /** Shows a spinner in place of the indicators and ignores presses and keys. */
  loading?: boolean;
  /** Called by the trigger's press, as the `onClick` the component forwards. */
  onClick?: (event: PointerEvent<HTMLSpanElement>) => void;
  onClearClick?: () => void;
  /** Replaces the press and the open keys: they call this and nothing else. */
  onInteract?: () => void;
  /** Moves the control out by its gutter so its content lines up. */
  opticallyAlign?: "end" | "start";
  pill?: boolean;
  ref?: Ref<HTMLSpanElement>;
  selected?: boolean;
  size?: SelectControlSize;
  StartIcon?: ComponentType<{ className?: string }>;
  variant?: SelectControlVariant;
}

const flag = (on: boolean | undefined) => (on === true ? "" : undefined);

/**
 * A loading control shows only the
 * spinner and ignores presses; the clear button needs a selected value.
 */
const indicatorState = ({
  disabled,
  dropdownIconType,
  hasClear,
  loading,
  selected,
}: {
  disabled: boolean;
  dropdownIconType: DropdownIconType;
  hasClear: boolean;
  loading: boolean;
  selected: boolean;
}) => {
  const showClear = hasClear && selected && !loading && !disabled;
  const showDropdown = dropdownIconType !== "none" && !loading;

  return {
    interactive: !loading && !disabled,
    showClear,
    showDropdown,
    showIndicators: showClear || loading || showDropdown,
  };
};

interface OpenHandlersOptions {
  elementRef: RefObject<HTMLSpanElement | null>;
  onClick: SelectControlProps["onClick"];
  onInteract: SelectControlProps["onInteract"];
  onKeyDown: SelectControlProps["onKeyDown"];
  onPointerDown: SelectControlProps["onPointerDown"];
}

/**
 * The press and key handlers. A press (not the right button) calls
 * `onPointerDown` and `onClick`, or `onInteract` alone; ArrowDown, ArrowUp and
 * Space do the same through a dispatched pointer down; Enter does nothing.
 */
const useOpenHandlers = ({
  elementRef,
  onClick,
  onInteract,
  onKeyDown,
  onPointerDown,
}: OpenHandlersOptions) => {
  const handlePointerDown = (event: PointerEvent<HTMLSpanElement>) => {
    if (event.button === 2) {
      return;
    }

    if (onInteract) {
      event.preventDefault();
      onInteract();
    } else {
      event.stopPropagation();
      onPointerDown?.(event);
      onClick?.(event);
    }
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLSpanElement>) => {
    switch (event.key) {
      case "ArrowDown":
      case "ArrowUp":
      case " ": {
        event.stopPropagation();
        event.preventDefault();

        if (onInteract) {
          onInteract();
        } else {
          elementRef.current?.dispatchEvent(
            new PointerEvent("pointerdown", {
              bubbles: true,
              cancelable: true,
              pointerType: "mouse",
            })
          );
        }

        break;
      }

      case "Enter": {
        break;
      }

      default: {
        onKeyDown?.(event);
      }
    }
  };

  return { handleKeyDown, handlePointerDown };
};

interface IndicatorsProps {
  clearLabel: string;
  dropdownIconType: DropdownIconType;
  loading: boolean;
  /** Set when the clear button shows. */
  onClearClick: (() => void) | undefined;
  pill: boolean;
  showDropdown: boolean;
}

/** The clear button, the loading spinner and the dropdown icon. */
const Indicators = ({
  clearLabel,
  dropdownIconType,
  loading,
  onClearClick,
  pill,
  showDropdown,
}: IndicatorsProps) => (
  <div className={styles.indicatorWrapper}>
    {onClearClick === undefined ? null : (
      <DataButton
        aria-label={clearLabel}
        className={styles.clear}
        color="secondary"
        data-ck-only-child={showDropdown ? undefined : ""}
        onClick={(event) => {
          event.stopPropagation();
          event.preventDefault();
          onClearClick();
        }}
        onPointerDown={(event) => {
          event.stopPropagation();
        }}
        onPointerEnter={setPressableScale}
        pill={pill}
        size="3xs"
        squircle={false}
        uniform
        variant={showDropdown ? "ghost" : "solid"}
      >
        <ClearIcon />
      </DataButton>
    )}
    {loading ? <LoadingIndicator className={styles.loadingIndicator} /> : null}
    {showDropdown ? <DropdownIcon iconType={dropdownIconType} /> : null}
  </div>
);

export const SelectControl = ({
  block,
  children,
  className,
  clearLabel = "Clear current value",
  disabled,
  disablePressable,
  dropdownIconType = "dropdown",
  invalid,
  loading = false,
  onClick,
  onClearClick,
  onInteract,
  onKeyDown,
  onPointerDown,
  onPointerEnter,
  opticallyAlign,
  pill = false,
  ref,
  selected = false,
  size = "md",
  StartIcon,
  variant = "outline",
  ...rest
}: SelectControlProps) => {
  const elementRef = useRef<HTMLSpanElement | null>(null);

  const { interactive, showClear, showDropdown, showIndicators } =
    indicatorState({
      disabled: disabled === true,
      dropdownIconType,
      hasClear: onClearClick !== undefined,
      loading,
      selected,
    });

  const { handleKeyDown, handlePointerDown } = useOpenHandlers({
    elementRef,
    onClick,
    onInteract,
    onKeyDown,
    onPointerDown,
  });

  return (
    <span
      aria-busy={loading ? "true" : undefined}
      aria-disabled={disabled}
      className={cn(styles.selectControl, className)}
      data-block={flag(block)}
      data-ck-disable-pressable={flag(disablePressable)}
      data-disabled={flag(disabled)}
      data-invalid={flag(invalid)}
      data-loading={flag(loading)}
      data-ck-optically-align={opticallyAlign}
      data-pill={flag(pill)}
      data-selected={selected}
      data-size={size}
      data-variant={variant}
      onKeyDown={interactive ? handleKeyDown : undefined}
      onPointerDown={interactive ? handlePointerDown : undefined}
      onPointerEnter={(event) => {
        if (disablePressable !== true) {
          setPressableScale(event);
        }

        onPointerEnter?.(event);
      }}
      ref={mergeRefs(elementRef, ref)}
      // oxlint-disable-next-line jsx-a11y/prefer-tag-over-role -- the trigger is a span with role button because it holds the clear button, and a button cannot contain a button
      role="button"
      tabIndex={disabled === true ? -1 : 0}
      {...rest}
    >
      {StartIcon ? <StartIcon className={styles.startIcon} /> : null}
      <span className={styles.triggerText}>{children}</span>
      {showIndicators ? (
        <Indicators
          clearLabel={clearLabel}
          dropdownIconType={dropdownIconType}
          loading={loading}
          onClearClick={showClear ? onClearClick : undefined}
          pill={pill}
          showDropdown={showDropdown}
        />
      ) : null}
    </span>
  );
};

"use client";

/* oxlint-disable react/no-react-children -- the group walks its children with React.Children to find the keyed elements, so loose and nested children behave as they do there */

import {
  afterFrames,
  useMediaQuery,
} from "@/components/dialog/dialog-layer";
import { useLatest } from "@/lib/dismissable-layer";
import { cn } from "@/lib/utils";
import {
  Children,
  isValidElement,
  useCallback,
  useEffect,
  useLayoutEffect,
  useReducer,
  useRef,
  useState,
} from "react";
import type { CSSProperties, ReactElement, ReactNode } from "react";

import styles from "./date-picker.module.css";

/*
 * A TransitionGroup: keeps a child
 * mounted after it leaves `children`, runs the entering and exiting phases as
 * data attributes on a wrapper span, and removes the child when the exit
 * duration ends. With reduced motion the group renders its children directly.
 */

interface Phase {
  enter: boolean;
  enterActive: boolean;
  exit: boolean;
  exitActive: boolean;
  interrupted: boolean;
}

type PhaseAction =
  | "done"
  | "enter-active"
  | "enter-before"
  | "exit-active"
  | "exit-before";

const IDLE: Phase = {
  enter: false,
  enterActive: false,
  exit: false,
  exitActive: false,
  interrupted: false,
};

const initialPhase = (preventMountTransition: boolean): Phase => ({
  ...IDLE,
  enter: !preventMountTransition,
});

const reducePhase = (state: Phase, action: PhaseAction): Phase => {
  switch (action) {
    case "enter-before": {
      return {
        enter: true,
        enterActive: false,
        exit: false,
        exitActive: false,
        interrupted: state.interrupted || state.exit,
      };
    }

    case "enter-active": {
      return {
        enter: true,
        enterActive: true,
        exit: false,
        exitActive: false,
        interrupted: false,
      };
    }

    case "exit-before": {
      return {
        enter: false,
        enterActive: false,
        exit: true,
        exitActive: false,
        interrupted: state.interrupted || state.enter,
      };
    }

    case "exit-active": {
      return {
        enter: false,
        enterActive: false,
        exit: true,
        exitActive: true,
        interrupted: false,
      };
    }

    case "done": {
      return IDLE;
    }

    default: {
      return state;
    }
  }
};

const flag = (on: boolean) => (on ? "" : undefined);

interface TransitionChildProps {
  children: ReactNode;
  className?: string;
  enterDuration: number;
  exitDuration: number;
  itemKey: string;
  onRemove: (key: string) => void;
  preventMountTransition: boolean;
  shouldRender: boolean;
  style?: CSSProperties;
}

const TransitionChild = ({
  children,
  className,
  enterDuration,
  exitDuration,
  itemKey,
  onRemove,
  preventMountTransition,
  shouldRender,
  style,
}: TransitionChildProps) => {
  // Stable per item, as the `removeChild`: a new function would restart the phase timers on every render.
  const removeChild = useCallback(() => {
    onRemove(itemKey);
  }, [onRemove, itemKey]);

  const [phase, dispatch] = useReducer(
    reducePhase,
    preventMountTransition,
    initialPhase
  );

  const mounted = useRef(false);
  const enterMs = useLatest(enterDuration);
  const exitMs = useLatest(exitDuration);

  useLayoutEffect(() => {
    let timer: number | undefined;

    if (shouldRender) {
      if (preventMountTransition && !mounted.current) {
        mounted.current = true;

        return;
      }

      dispatch("enter-before");
    } else {
      dispatch("exit-before");
    }

    const cancel = afterFrames(() => {
      if (shouldRender) {
        dispatch("enter-active");
        // oxlint-disable-next-line react/immutability -- local to this effect or callback, not render state; oxlint 1.91 misreports it
        timer = window.setTimeout(() => {
          dispatch("done");
        }, enterMs.current);
      } else {
        dispatch("exit-active");
        timer = window.setTimeout(removeChild, exitMs.current);
      }
    });

    // oxlint-disable-next-line consistent-return -- the first branch returns early when there is nothing to undo
    return () => {
      cancel();

      if (timer !== undefined) {
        window.clearTimeout(timer);
      }
    };
  }, [shouldRender, preventMountTransition, removeChild, enterMs, exitMs]);

  useEffect(
    () => () => {
      mounted.current = false;
    },
    []
  );

  return (
    <span
      className={cn(className, styles.transitionChild)}
      data-entering={flag(phase.enter)}
      data-entering-active={flag(phase.enterActive)}
      data-exiting={flag(phase.exit)}
      data-exiting-active={flag(phase.exitActive)}
      data-interrupted={flag(phase.interrupted)}
      style={style}
    >
      {children}
    </span>
  );
};

interface Item {
  element: ReactElement;
  key: string;
  preventMountTransition: boolean;
  shouldRender: boolean;
}

const keyedChildren = (children: ReactNode): ReactElement[] => {
  const elements: ReactElement[] = [];

  for (const child of Children.toArray(children)) {
    if (isValidElement(child) && child.key !== null) {
      elements.push(child);
    }
  }

  return elements;
};

/** The child list with the default `append` insert method. */
const mergeItems = (children: ReactElement[], items: Item[]): Item[] => {
  const incoming = new Set(children.map((child) => String(child.key)));
  const existing = new Set(items.map((item) => item.key));
  const added: Item[] = [];

  for (const child of children) {
    const key = String(child.key);

    if (!existing.has(key)) {
      added.push({
        element: child,
        key,
        preventMountTransition: false,
        shouldRender: true,
      });
    }
  }

  const updated = items.map((item) => ({
    ...item,
    element:
      children.find((child) => String(child.key) === item.key) ?? item.element,
    shouldRender: incoming.has(item.key),
  }));

  return [...updated, ...added];
};

export interface TransitionGroupProps {
  children?: ReactNode;
  className?: string;
  enterDuration?: number;
  exitDuration?: number;
  /** Children present on the first render do not animate in (default true). */
  preventInitialTransition?: boolean;
  style?: CSSProperties;
}

/** The TransitionGroup: every keyed child gets a `span` wrapper. */
export const TransitionGroup = ({
  children,
  className,
  enterDuration = 0,
  exitDuration = 0,
  preventInitialTransition = true,
  style,
}: TransitionGroupProps) => {
  const reducedMotion = useMediaQuery("(prefers-reduced-motion: reduce)");
  const elements = keyedChildren(children);

  const [items, setItems] = useState<Item[]>(() =>
    elements.map((element) => ({
      element,
      key: String(element.key),
      preventMountTransition: preventInitialTransition,
      shouldRender: true,
    }))
  );

  const [seenChildren, setSeenChildren] = useState(children);

  // The component merges in a layout effect. Merging while rendering commits the
  // same state before paint without an extra render.
  if (children !== seenChildren) {
    setSeenChildren(children);
    setItems((current) => mergeItems(elements, current));
  }

  const removeChild = useCallback((key: string) => {
    setItems((current) => current.filter((item) => item.key !== key));
  }, []);

  if (reducedMotion) {
    return (
      <>
        {elements.map((element) => (
          <span className={className} key={element.key} style={style}>
            {element}
          </span>
        ))}
      </>
    );
  }

  const latest = new Map(
    elements.map((element) => [String(element.key), element])
  );

  return (
    <>
      {items.map((item) => (
        <TransitionChild
          className={className}
          enterDuration={enterDuration}
          exitDuration={exitDuration}
          itemKey={item.key}
          key={item.key}
          onRemove={removeChild}
          preventMountTransition={item.preventMountTransition}
          shouldRender={item.shouldRender}
          style={style}
        >
          {latest.get(item.key) ?? item.element}
        </TransitionChild>
      ))}
    </>
  );
};

/*
 * The time zones of the DateTime: the system zone, UTC, fixed offsets and IANA
 * names, each answering with an offset in minutes for an instant.
 */

const MS_PER_MINUTE = 60_000;
const MS_PER_SECOND = 1000;
const MINUTES_PER_HOUR = 60;
const TWO_DIGITS = 2;
const SHORT_YEAR_LIMIT = 100;

/** Zero-pads the absolute value to `digits`, keeping a minus sign. */
export const pad = (value: number | string, digits: number) => {
  const text = String(Math.abs(Number(value)));
  const sign = Number(value) < 0 ? "-" : "";

  return `${sign}${text.padStart(digits, "0")}`;
};

/** The locale Luxon falls back to: the system's. */
export const systemLocale = () =>
  new Intl.DateTimeFormat().resolvedOptions().locale;

const systemZoneName = () =>
  new Intl.DateTimeFormat().resolvedOptions().timeZone;

const ianaFormatters = new Map<string, Intl.DateTimeFormat>();

const ianaFormatter = (name: string) => {
  let formatter = ianaFormatters.get(name);

  if (formatter === undefined) {
    formatter = new Intl.DateTimeFormat("en-US", {
      day: "numeric",
      era: "short",
      hour: "numeric",
      hourCycle: "h23",
      minute: "numeric",
      month: "numeric",
      second: "numeric",
      timeZone: name,
      year: "numeric",
    });
    ianaFormatters.set(name, formatter);
  }

  return formatter;
};

const FIXED_ZONE_PREFIX = "utc";
const DIGITS = /^\d{1,2}$/u;

/** Luxon `formatOffset(offset, format)` for an offset in minutes. */
const formatMinutes = (offset: number, style: OffsetStyle) => {
  const hours = Math.trunc(Math.abs(offset / MINUTES_PER_HOUR));
  const minutes = Math.trunc(Math.abs(offset % MINUTES_PER_HOUR));
  const sign = offset >= 0 ? "+" : "-";

  if (style === "short") {
    return `${sign}${pad(hours, TWO_DIGITS)}:${pad(minutes, TWO_DIGITS)}`;
  }

  if (style === "techie") {
    return `${sign}${pad(hours, TWO_DIGITS)}${pad(minutes, TWO_DIGITS)}`;
  }

  return `${sign}${hours}${minutes > 0 ? `:${minutes}` : ""}`;
};

/** Luxon `parseZoneInfo`: the zone name Intl prints for an instant. */
const parseZoneInfo = (
  ts: number,
  format: Intl.DateTimeFormatOptions["timeZoneName"],
  locale: string,
  timeZone: string | undefined
): string | null => {
  const options: Intl.DateTimeFormatOptions = {
    day: "2-digit",
    hour: "2-digit",
    hourCycle: "h23",
    minute: "2-digit",
    month: "2-digit",
    timeZoneName: format,
    year: "numeric",
  };

  if (timeZone !== undefined) {
    options.timeZone = timeZone;
  }

  const parsed = new Intl.DateTimeFormat(locale, options)
    .formatToParts(new Date(ts))
    .find((part) => part.type.toLowerCase() === "timezonename");

  return parsed?.value ?? null;
};

type ZoneKind = "fixed" | "iana" | "system";

export type OffsetStyle = "narrow" | "short" | "techie";

/** Luxon `Zone`: an offset in minutes for any instant. */
export class Zone {
  readonly kind: ZoneKind;

  readonly name: string;

  private readonly fixedOffset: number;

  private constructor(kind: ZoneKind, name: string, fixedOffset = 0) {
    this.kind = kind;
    this.name = name;
    this.fixedOffset = fixedOffset;
  }

  static readonly system = new Zone("system", "system");

  static readonly utc = new Zone("fixed", "UTC");

  /** Luxon `FixedOffsetZone.instance`: zero is UTC, others are named by `narrow`. */
  static fixed(minutes: number): Zone {
    if (minutes === 0) {
      return Zone.utc;
    }

    return new Zone("fixed", `UTC${formatMinutes(minutes, "narrow")}`, minutes);
  }

  /** A zone, "system"/"local", "UTC"/"GMT", "UTC+5:30" or an IANA name. */
  static from(zone: Zone | string | undefined): Zone {
    if (zone instanceof Zone) {
      return zone;
    }

    if (zone === undefined || zone === "local" || zone === "system") {
      return Zone.system;
    }

    const lower = zone.toLowerCase();

    if (lower === "utc" || lower === "gmt") {
      return Zone.utc;
    }

    const minutes = Zone.parseFixedOffset(lower);

    return minutes === undefined ? new Zone("iana", zone) : Zone.fixed(minutes);
  }

  /** "utc+5", "utc-05:30" or "utc+0530" as signed minutes. */
  private static parseFixedOffset(lower: string): number | undefined {
    const sign = lower.charAt(FIXED_ZONE_PREFIX.length);

    if (
      !lower.startsWith(FIXED_ZONE_PREFIX) ||
      (sign !== "+" && sign !== "-")
    ) {
      return undefined;
    }

    const rest = lower.slice(FIXED_ZONE_PREFIX.length + 1);

    // Luxon's fixed-offset grammar: one or two hour digits, optional :mm.
    if (!/^\d{1,2}(?::\d{2})?$/u.test(rest)) {
      return undefined;
    }

    const [head = "", clock] = rest.split(":");
    const hourText = clock === undefined ? head.slice(0, TWO_DIGITS) : head;
    const minuteText = clock ?? head.slice(TWO_DIGITS);
    const minutes = minuteText === "" ? "0" : minuteText;

    if (!DIGITS.test(hourText) || !DIGITS.test(minutes)) {
      return undefined;
    }

    const total = Number(hourText) * MINUTES_PER_HOUR + Number(minutes);

    return sign === "-" ? -total : total;
  }

  /** The offset from UTC, in minutes, at the instant `ts`. */
  offset(ts: number): number {
    if (this.kind === "fixed") {
      return this.fixedOffset;
    }

    if (this.kind === "system") {
      return -new Date(ts).getTimezoneOffset();
    }

    const values = new Map<string, number>();
    let isBc = false;

    for (const part of ianaFormatter(this.name).formatToParts(new Date(ts))) {
      if (part.type === "era") {
        isBc = part.value === "BC";
      } else if (part.type !== "literal") {
        values.set(part.type, Math.trunc(Number(part.value)));
      }
    }

    const hour = values.get("hour") ?? 0;
    const parsedYear = values.get("year") ?? 0;
    const year = isBc ? -Math.abs(parsedYear) + 1 : parsedYear;
    const month = values.get("month") ?? 1;
    const day = values.get("day") ?? 1;

    const wallClock = new Date(
      Date.UTC(
        year,
        month - 1,
        day,
        hour === 24 ? 0 : hour,
        values.get("minute") ?? 0,
        values.get("second") ?? 0
      )
    );

    // Date.UTC maps the years 0 to 99 to 1900 to 1999.
    if (year >= 0 && year < SHORT_YEAR_LIMIT) {
      wallClock.setUTCFullYear(year, month - 1, day);
    }

    const utcOfLocal = wallClock.getTime();

    const over = ts % MS_PER_SECOND;
    const wholeSeconds = ts - (over >= 0 ? over : MS_PER_SECOND + over);

    return (utcOfLocal - wholeSeconds) / MS_PER_MINUTE;
  }

  /** Luxon `formatOffset`: `narrow` +H[:m], `short` +HH:mm, `techie` +HHmm. */
  formatOffset(ts: number, style: OffsetStyle): string {
    return formatMinutes(this.offset(ts), style);
  }

  /**
   * Luxon `offsetName`: a fixed zone is named by its offset ("UTC+5:30"); the
   * others ask Intl for the zone's name in `locale`.
   */
  offsetName(
    ts: number,
    format: Intl.DateTimeFormatOptions["timeZoneName"],
    locale: string
  ): string | null {
    if (this.kind === "fixed") {
      return this.name;
    }

    return parseZoneInfo(
      ts,
      format,
      locale,
      this.kind === "iana" ? this.name : undefined
    );
  }

  get zoneName(): string {
    return this.kind === "system" ? systemZoneName() : this.name;
  }

  equals(other: Zone): boolean {
    return this.kind === other.kind && this.name === other.name;
  }
}

